programs.sol:
"""Approximate a local response to written backslash escape notation.

Newline escapes, adjacent tab escapes, hexadecimal byte escapes, escaped
quotes and doubled backslashes receive positive predictions. Separately
tokenized n/t/r can complete the previous backslash; neighboring written
whitespace escapes reinforce one another. Bare slashes are weakened after
digits, individual letters and mathematical opening punctuation. Most other
text, including actual line breaks alone, receives a near-zero prediction.
Only two preceding token strings are retained, resetting at document changes.
"""
READS = ()


def written_space(token, before):
    return token.endswith(('\\n', '\\t', '\\r')) or (
        token in ('n', 't', 'r') and before.endswith('\\'))


def bare_slash(previous, repeated, spaced):
    if repeated:
        return 2.5 if spaced else 4.1
    if '\\' in previous:
        return 2.1 if spaced else 2.9
    if not previous:
        return 1.5
    end, word = previous[-1], previous.strip()
    if end in '\n\r':
        return -0.15
    if end.isdigit():
        return -0.35
    if end == '{':
        return -0.3 if spaced else -0.85
    if end in '(=+-<>[':
        return -0.15 if spaced else 0.0
    if end in '})]$':
        return (0.1 if end in '}$' else 0.0) if spaced else {
            '}': 0.3, ')': 1.65, ']': 1.25, '$': 0.75}[end]
    if end in ';:,':
        return 0.5 if spaced else 1.45
    if previous.isspace():
        return 0.65 if spaced else 0.2
    if len(word) == 1 and word.isalpha():
        return -0.15
    if word and word[0].isupper() and word.isalpha():
        return 0.8 if spaced else 2.2
    return 0.95 if spaced else 1.4


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, before = carry[1:] if carry and carry[0] == doc else ('', '')
    repeated = written_space(previous, before)
    s, value = token.strip(), 0.0
    if token in ('n', 't', 'r'):
        value = -0.04
        if previous.endswith('\\'):
            value = {'n': 1.4, 't': 1.1, 'r': 0.5}[token]
            if token == 'n':
                count = len(previous) - len(previous.rstrip('\\'))
                value /= count ** 0.5
    elif '\\' in token:
        if token == '\\n':
            value = 2.9 if repeated else 1.35
            if not repeated and previous and previous[-1].isdigit():
                value = 0.95
        elif token == '\\t':
            value = 2.7 if repeated else 0.0
        elif token.startswith('\\x'):
            value = 3.0 if repeated else (1.2 if token == '\\x' else 0.85)
        elif '\\\\' in token:
            value = 1.15 if token.startswith(' ') else 2.1
            if len(s) >= 4 and set(s) == {'\\'}:
                value = 2.7
            if repeated or '\\' in previous:
                value += 0.4
            elif previous.endswith(('(', '{', '=')):
                value -= 0.6
        elif '\\"' in token:
            value = 1.35 if token.startswith('(') else 1.55
            if s.endswith('\\') and ',' not in s:
                value = 2.3
            elif s.endswith((',', ':', ']', '>')) or ',' in s:
                value = 0.95
            if token.startswith('\\'):
                if repeated or '\\' in previous:
                    value += 1.1
                elif previous and previous[-1].isdigit():
                    value -= 0.55
        elif s == '\\':
            value = bare_slash(previous, repeated, token.startswith(' '))
        elif s.endswith('\\'):
            value = 1.05
            if s[0] in '{([$^+-=' and not s.startswith('()'):
                value = -0.1
            elif s[0] == '}':
                value = 1.2 if repeated else 0.15
            elif s[0] == '*':
                value = 2.6
            elif s[0] == '_':
                value = 1.7 if '\\' in previous else -0.1
            elif s[0] in ',]':
                value = 0.5
            elif s[0] == ':':
                value = 1.6
        else:
            value = 1.0 if '\n' in token else 0.1
            if s in ('\\$', "\\'", '\\/'):
                value = 0.8
    elif s == '&#':
        value = 0.5
    return (doc, token, previous), float(value)

programs.luna:
"""Mark visible backslash escapes, common in serialized text and source code."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, old_doc = carry if carry is not None else ("", None)

    if doc != old_doc:
        previous = ""

    # The component is most active on the backslash itself and on the n
    # that completes a split "\\n" escape.
    if "\\" in token:
        value = 1.5
    elif token == "n" and previous.endswith("\\"):
        value = 1.35
    else:
        value = 0.0

    return (token, doc), float(value)

programs.sol:
"""A lexical absence/avoidance signal, rather than general negative sentiment.

Avoidance and Chinese exemption (免) are strongest. No and without are weaker.
Not/-n't respond negatively chiefly after action auxiliaries, not forms of be.
Smaller responses cover prevention/reduction and the word before.
Unrecognized tokens give zero; document boundaries reset the previous token.
"""
READS = ()

# Grammatical contexts for full and contracted English negation.
NOT_AFTER = {
    'do': -1.45, 'does': -1.27, 'did': -1.11, 'should': -1.39,
    'can': -1.25, 'will': -1.26, 'would': -1.04, 'could': -1.05,
    'must': -1.25, 'may': -0.82, 'might': -0.82, 'need': -0.88,
    'have': -0.38, 'has': -0.45, 'had': -0.50, 'but': 0.31,
}
CONTRACTED = {
    'don': -1.22, 'doesn': -1.15, 'didn': -1.01, 'can': -1.28,
    'won': -1.04, 'wouldn': -0.95, 'couldn': -1.04, 'shouldn': -0.91,
    'haven': -0.53, 'hasn': -0.52, 'hadn': -0.42,
    'isn': -0.13, 'aren': -0.19, 'wasn': -0.08, 'weren': -0.18,
}
AVOID = {'avoid': -4.6, 'avoiding': -4.17, 'avoids': -4.45,
         'avoided': -3.7, 'avoidance': -2.75,
         '免': -6.7, '避免': -5.3, '以免': -4.6, '难免': -3.3}

# A few smaller absence, prevention and reduction word families.
WEAKER = {}
for words, strength in (
    ('cannot', -1.16), ('never', -0.76),
    ('hardly rarely before', -0.50), ('prevent', -1.30),
    ('prevents minimize unnecessary', -0.90),
    ('preventing minimizing minimized', -0.75),
    ('prevention eliminate eliminating reduce reducing otherwise', -0.50),
    ('sans ohne без', -1.0),
    ('无 無 没有 沒有 不能 无法 都不 就不', -0.8),
    ('不要 不会', -1.15), ('不', -0.37), ('没 沒', -0.57),
    ('防止', -1.8), ('防 省 减少 消除 预防', -0.6),
    ('✗ ❌', -0.8),
):
    WEAKER.update(dict.fromkeys(words.split(), strength))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    raw = text.strip()
    # The exemption character can finish on a separate UTF-8 continuation token.
    if '\ufffd' in raw and prefix.text_prefixes[-1].endswith('免'):
        raw = '免'
    word, prev = raw.lower(), previous.strip().lower()
    value = WEAKER.get(word, 0.0)
    if word == 'not':
        value = NOT_AFTER.get(prev, 0.13 if raw == 'not' else 0.28)
        if previous.strip() == 'Do':
            value = -1.8
    elif word in {"'t", '’t'}:
        value = CONTRACTED.get(prev, 0.0)
    elif word.lstrip('/_.-("') == 'no':
        value = -1.6 if text.startswith(' ') else -1.1
        if raw.lower() != raw:
            value = -1.4 if raw != 'NO' else -1.1
        elif raw.startswith('/'):
            value = -1.85
        elif raw.startswith('_'):
            value = -1.05
        elif raw.startswith(('.', '-')):
            value = -1.6
        if raw == 'no' and prev in {'que', 'y', 'pero', 'si', 'yo', 'se', 'lo'}:
            value = -0.65  # Spanish 'no' negates a verb, rather than a noun.
        elif raw == 'no' and prev in {'is', 'are', 'was', 'have', 'has', 'with'}:
            value = -1.8
    elif word.lstrip('_') == 'without':
        value = -1.72 if raw == 'without' and text.startswith(' ') else -1.5
        if raw == 'WITHOUT':
            value = -1.87
    elif word in AVOID:
        value = AVOID[word]
        if word == 'avoid' and raw != 'avoid':
            value = -4.2
        if word == 'avoid' and not text.startswith(' '):
            value = -3.65
    elif prev == 'avoid' and word in {'ance', 'ing', 'ed', 'able'}:
        value = -2.5
    return (doc, text), float(value)

programs.luna:
"""Recognize denial, limitation, and prevention language.

Most explicit negators get a moderate negative pulse. Avoidance verbs are
stronger in the harvested examples, while hedges and limiting language get
a smaller one. The program uses the preceding word only for English -'t
contractions and resets that context when the document changes.
"""
READS = ()

NEGATORS = {
    "not", "no", "never", "none", "neither", "nor", "nobody", "nothing",
    "nowhere", "without", "cannot", "不", "没", "没有", "无", "都不", "不要",
}
AVOIDANCE = {"avoid", "avoids", "avoided", "avoiding", "避免"}
LIMITING = {
    "hardly", "rarely", "before", "prevent", "prevents", "prevented",
    "prevention", "minimize", "minimized", "minimizing", "absent", "lack",
    "lacking", "消除",
}
CONTRACTION_STEMS = {
    "don", "doesn", "didn", "isn", "aren", "wasn", "weren", "hasn",
    "haven", "hadn", "won", "wouldn", "couldn", "shouldn", "mustn",
    "needn", "shan", "ca", "can",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    previous, old_document = carry if carry is not None else ("", None)
    document = prefix.document_ids[-1]
    if document != old_document:
        previous = ""

    value = 0.0
    if token in NEGATORS:
        value = -1.0
    elif token in AVOIDANCE:
        value = -2.0
    elif token in LIMITING:
        value = -0.7
    elif token in ("'t", "n't") and previous in CONTRACTION_STEMS:
        value = -1.0
    return (token, document), float(value)

programs.haiku:
"""Number and singleness words: a negative response, sized by the word.

On almost all text the component is near zero. It turns negative on a few families of words,
each with its own typical size:
  - 'single' (about -4.7), and the Chinese 單 / 单 (about -7)
  - the numerals two to seven, and 'individual', 'alone', 'multi': about -1
  - 'one', the numerals eight to twelve, and 'sole', 'solo', 'double', 'multiple': about -0.7
Anything else predicts 0. The size is set by the word, not its context.
"""

READS = ()

SINGLE = {"single", "ingle"}
CJK_SINGLE = {"單", "单"}
COUNT = {"two", "three", "four", "five", "six", "seven", "individual", "alone", "multi"}
SMALL = {"one", "eight", "nine", "eleven", "twelve", "sole", "solo", "double", "multiple",
         "mult", "plurality", "manual"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in SINGLE:
        return None, -4.7
    if word in CJK_SINGLE:
        return None, -7.3
    if word in COUNT:
        return None, -1.0
    if word in SMALL:
        return None, -0.7
    return None, 0.0

programs.sol:
"""Estimate an additive/next-step marker feature.

The large responses are conjunctions, sequencing words, polite requests,
and their Chinese and several other-language counterparts. Lowercase
'and' is stronger at a clause boundary or in technical notation than in
ordinary word pairs, especially 'between ... and' and 'both ... and'.
Ordinary contrast/inference and time-reference words get weak negative
values. Case and token-leading whitespace distinguish several forms.
Only a short, document-local text suffix and the last token are retained.
"""
import re

READS = ()

# Adding another item, advancing a sequence, or introducing an instruction.
MARKERS = {
    'AND': 0.28, '_and': 1.05, '-and': 0.50,
    'THEN': 1.0,
    'finally': 1.25,
    'lastly': 1.60, 'Lastly': 1.60,
    'etc': 0.85, 'respectively': 0.88, 'separately': 0.45,
    'please': 0.72, 'Please': 0.75,
    'now': 0.13, 'Now': 0.60,
    'also': 0.07, 'Also': 0.80,
    'Moreover': 0.64, 'Furthermore': 0.55,
    'Similarly': 0.55, 'Additionally': 0.52,
}
TRANSLATED_MARKERS = {
    # Chinese: and; and not/will; then/again; finally; after.
    '并': 3.50, '，并': 3.39, '並': 3.80,
    '并且': 1.60, '并不': 0.69, '并将': 2.40,
    '然后': 2.08, '然後': 2.28, '然后再': 2.27,
    '再': 1.20, '最后': 1.55, '最後': 1.35,
    '后': 0.60, '後': 0.48, '之后': 0.55,
    # Simultaneously, respectively, and also, please.
    '同时': 1.07, '同時': 0.84, '同时也': 0.92,
    '分别': 0.96, '且': 0.40, '以及': 0.33,
    '请': 0.83, '請': 0.84, '，请': 1.02,
    # Japanese and/also; Korean and/after; Vietnamese then/and.
    'そして': 1.80, 'また': 0.64,
    '하고': 1.11, '고': 0.62, '그리고': 1.38, '후': 0.82,
    'rồi': 1.53, 'và': 0.27,
    # French then; Russian also/then.
    'puis': 0.85, 'Также': 0.92, 'затем': 1.15,
}

# In contrast, ordinary opposition, inference, and time-reference words
# have small negative responses (these are the lowercase token forms).
WEAK_LINKS = {
    'but': -0.05, 'while': -0.09, 'yet': -0.16,
    'instead': -0.15, 'still': -0.10, 'however': -0.025,
    'so': -0.084, 'thus': -0.18, 'therefore': -0.10, 'hence': -0.27,
    'next': -0.095, 'later': -0.15, 'earlier': -0.19,
    'before': -0.04, 'after': -0.025,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, previous_value = '', '', 0.0
    else:
        _, recent, previous, previous_value = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = MARKERS.get(word, TRANSLATED_MARKERS.get(word, 0.0))
    if token[:1].isspace() and word in WEAK_LINKS:
        value = WEAK_LINKS[word]
    if word in ('and', 'or', 'then'):
        # Baseline, comma, closing bracket, and technical-context strengths.
        base, comma, closing, technical = {
            'and': (0.07, 0.40, 0.14, 0.20),
            'or': (-0.13, 0.28, 0.09, 0.07),
            'then': (0.73, 0.18, 0.07, 0.14),
        }[word]
        value = base
        if ',' in previous:
            value += comma
        if ')' in previous or ']' in previous:
            value += closing
        if '"' in previous or '”' in previous:
            value += 0.10 if word == 'and' else 0.05
        if re.search(r'[.!?]\s*$', previous) or ';' in previous:
            value += comma * 0.4
        if previous and not previous.strip():
            value += comma * 0.5
        if not previous:
            value += comma * 0.5
        if re.search(r'`|\\|[=<>_{}]', recent):
            value += technical
        if '$' in recent:
            value += 0.06
        if '`' in recent:
            value += technical
        if word == 'and':
            if '$' in previous or '`' in previous:
                value += 0.12
            if re.search(r'\bbetween\b[^,;.!?]*$', recent, re.I):
                value -= 0.24
            if re.search(r'\bboth\b[^,;.!?]*$', recent, re.I):
                value -= 0.10
        elif word == 'then':
            before = previous.strip().lower()
            if before in ('since', 'until', 'till', 'before', 'by', 'back'):
                value -= 0.35
            elif before == 'but':
                value -= 0.19
            elif before == 'and':
                value += 0.15
    elif word == '&&':
        value = 1.03 if token[:1].isspace() else 0.65
    elif word == 'endl':
        value = 0.78
    elif word == '||':
        value = 0.23
    elif word in ('And', 'Then', 'Finally'):
        spaced, unspaced = {
            'And': (0.90, 1.01),
            'Then': (1.28, 1.37),
            'Finally': (1.93, 1.68),
        }[word]
        value = spaced if token[:1].isspace() else unspaced
    elif word in ('Now', 'Also', 'Additionally') and not token[:1].isspace():
        value += 0.17
    elif word == ',':
        if previous.strip() in ('Finally', 'finally'):
            value = 0.27 * previous_value
        elif previous.strip() in ('Then', 'Also', 'Now'):
            value = 0.09
    return (doc, (recent + token)[-240:], token, value), float(value)

programs.haiku:
"""Connective words that link one clause or step to the next.

This component fires on words that join one step or clause to the next. Its strongest
responses are the Chinese word 并 ("and, also") and its variants, then the other Chinese
and Japanese words for "and then" (然后, 再, 同时, そして). Next come sentence-opening
sequencing words ("Finally", "Then", "Also", "And"), "then" in the middle of a sentence
("and then run it"), and "&&". "and" right after a comma or closing bracket, where it joins
two clauses, is moderate; "and" between two nouns is weak, and "between X and Y" is slightly
negative. "and" as a piece of an identifier or hyphenated word ("_and", "-and") is moderate.
Everything else is 0.
"""

READS = ()

# Chinese word 并 ("and, also") and its traditional form: the strongest responses
STRONG_CJK = {"并", "並"}
# other Chinese and Japanese words for "and then", "at the same time", "again"
CJK_THEN = {"然后", "然後", "再", "同时", "同時", "そして", "最后", "最後"}
# English sequencing words that open a sentence (capitalised), with typical size
OPENERS = {"Finally": 2.0, "Then": 1.3, "Also": 1.0, "And": 1.0, "Now": 0.6,
           "Etc": 0.8, "Please": 0.8, "Moreover": 0.6, "Furthermore": 0.6,
           "Similarly": 0.6, "Additionally": 0.5}
# lowercase words used mid-sentence
MIDWORDS = {"finally": 1.2, "then": 0.9, "etc": 0.8, "respectively": 0.9, "please": 0.7}
# words after which an "and" joins two clauses
CLAUSE_END = {",", "),", ")", "`", ";"}


def step(carry, prefix, upstream):
    words = prefix.token_strings[-2:]
    word = words[-1].strip().lstrip("，,")
    before = words[-2].strip() if len(words) > 1 else ""
    if word in STRONG_CJK:
        return carry, 3.0
    if word in CJK_THEN:
        return carry, 1.5
    if word in ("请", "請"):
        return carry, 0.8
    if word in OPENERS:
        return carry, OPENERS[word]
    if word in MIDWORDS:
        return carry, MIDWORDS[word]
    if word == "&&":
        return carry, 1.0
    if word.lstrip("_-") == "and" and word != "and":
        return carry, 0.6
    if word == "and":
        if before in CLAUSE_END:
            return carry, 0.5
        if "between" in "".join(prefix.token_strings[-7:-1]):
            return carry, -0.2
        return carry, 0.15
    return carry, 0.0

programs.luna:
"""Estimate a positive pulse on conjunctions and discourse transitions.

The strongest cues are sentence-initial English linkers, English and/then,
logical &&, and Chinese additive or sequencing words. Case and script help
separate sentence-opening linkers from ordinary lowercase uses; other contexts
and the size of each real pulse are not modeled.
"""
READS = ()

PUNCTUATION = " \t\r\n,.;:!?()[]{}\"'“”。，"


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip(PUNCTUATION)
    word = raw.lower()
    title = raw[:1].isupper() and not raw.isupper()

    if word == "and":
        return None, 0.95 if title else 0.18
    if word == "&&":
        return None, 1.05
    if word == "then":
        return None, 1.25 if title else 0.85
    if word == "finally":
        return None, 1.5 if title else 1.25
    if word in {"并", "並"}:
        return None, 3.4
    if word in {"最后", "最後", "然後", "然后"}:
        return None, 2.0 if word not in {"最后", "最後"} else 1.5
    if word == "同时":
        return None, 1.1
    if word in {"moreover", "furthermore"}:
        return None, 0.85 if title else 0.5
    if word == "now":
        return None, 0.8 if title else 0.15
    if word == "also":
        return None, 0.8 if title else 0.2
    if word in {"etc", "please"}:
        return None, 0.75
    return None, 0.0

programs.sol:
"""Recognize occasional events, indefinite quantities, and conditional cases.

'Sometimes' and its translations are the strongest lexical cues. Other
frequency words, 'some', and partial-quantity words are weaker. Short idioms
such as 'at times' and 'in some cases' strengthen the prediction; a bare
programming 'case' does not. The last 64 characters supply only this phrase
context, and are reset at document boundaries. Unrecognized tokens get zero.
These are rounded training-based strengths, not universal semantic scores.
"""
import re

READS = ()

FREQUENCY = {
    'sometimes': 6.4, 'occasionally': 3.8, 'occasional': 2.25,
    'often': 1.72, 'usually': 0.82, 'frequently': 0.71,
    'rarely': 0.64, 'seldom': 0.43, 'typically': 0.32,
    'some': 1.48, 'somewhat': 0.61, 'somehow': 0.65,
    'somewhere': 0.45, 'partly': 1.0, 'certain': 0.38,
    'many': 0.16, 'depending': 0.5,
}
# Frequency, quantity, and conditional-case cues in other languages.
TRANSLATIONS = {
    '有时': 5.5, '有时候': 5.9, '偶尔': 2.75,
    '常常': 1.43, '往往': 1.78, '通常': 0.67,
    '有些': 2.5, '有些人': 2.25, '一些': 1.14, '有一些': 1.62,
    '某些': 1.28, '不少': 0.8, '很多': 0.57, '许多': 0.45,
    'иногда': 4.47, 'часто': 1.13, 'некоторые': 1.2,
    'souvent': 1.3, 'quelque': 0.35, 'quelques': 0.42,
    'oft': 0.6, 'einige': 0.6, 'algunos': 1.0,
    'بعض': 1.63, 'случае': 0.87,
    '場合': 1.19, '場合は': 0.7,
    'ったり': 1.49, 'たり': 1.32, 'したり': 1.19,
    'こともある': 3.57, 'こともあります': 3.0, 'もあります': 1.32,
}


def ends(before, pattern):
    return re.search(pattern + r'\s*$', before) is not None


def activation(token, before):
    word = token.strip().lower()
    if word in FREQUENCY:
        value = FREQUENCY[word]
        if token.strip()[:1].isupper():
            value += {'sometimes': 0.3, 'often': 0.3, 'usually': 0.55,
                      'many': 0.2, 'certain': 0.2}.get(word, 0.0)
        if token == 'Sometimes':
            value = 7.4
        elif token == 'Some':
            value = 1.74
        if word == 'some' and ends(before, r'\bin'):
            value = 1.83
        return value
    if word in TRANSLATIONS:
        return TRANSLATIONS[word]
    if word == 'entimes' and before.endswith('oft'):
        return 2.6
    if word == 'fois':  # French 'parfois' is often split into par + fois.
        if before.endswith('par'):
            return 4.2
        if before.endswith('quelque'):
            return 2.4
        return 0.4
    if word == 'most':
        if ends(before, r'\bthe'):
            return 0.11  # Superlative, not a quantity: 'the most ...'.
        if ends(before, r'\bin'):
            return 0.73
