"""Approximate comment-punctuation responses, plus four location particles.

Double slashes are stronger at a real line's left margin than inline or after
an escaped newline. Line-leading stars are stronger near a block-comment
opener; stars containing a newline are weaker. Hashes require code-like text
or a numbered listing. A line-leading blockquote marker has a small response.
The four exact Japanese/Korean particles receive fixed values; other tokens
are zero. All context resets at document boundaries. Values were estimated
from harvested training windows, not from model weights.
"""
import re

READS = ()
LOCATION_PARTICLES = {"に": 1.24, "에": 0.79, "로": 0.63, "으로": 0.53}
MARGIN = re.compile(r"^\s*(?:\d+\s+)?$")
LISTING = re.compile(r"^\s*\d+\s")
CODE = re.compile(r"[;{}=]|\b(?:import|def|return|class|print)\b")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, escaped, code, comment_age = "", False, False, 100
    else:
        _, line, escaped, code, comment_age = carry
    token = prefix.token_strings[-1]
    marker = token.strip()
    margin = bool(MARGIN.fullmatch(line))
    listing = bool(LISTING.match(line))
    value = LOCATION_PARTICLES.get(token, 0.0)
    if marker == "//":
        value = 1.16 if margin and not escaped else 0.76
    elif marker == "/*":
        value = 0.50 if "\n" in token else 0.65
    elif marker == "*" and token.startswith(" ") and margin:
        if "\n" in token:
            value = 0.56
        elif escaped:
            value = 0.69
        elif listing:
            value = 0.29
        else:
            value = 1.25 if comment_age < 6 else 0.70
    elif marker == "*\\" and margin:
        value = 0.33
    elif marker == "#" and (code or listing):
        if not margin:
            value = 0.28
        elif listing:
            value = 0.47
        elif escaped:
            value = 0.72 if token.startswith(" ") else 0.23
        else:
            value = 0.76
    elif marker == ">" and margin:
        value = 0.18
    code = code or bool(CODE.search(token))
    if "/*" in token:
        comment_age = 0
    if "*/" in token:
        comment_age = 100
    line += token
    pieces = re.split(r"(\n|\\n)", line)
    if len(pieces) > 1:
        comment_age += (len(pieces) - 1) // 2
        escaped = pieces[-2] == "\\n"
        line = pieces[-1]
    return (doc, line[-200:], escaped, code, comment_age), value

programs.haiku:
"""Layer-0 MLP down-projection component 1734: a comment-opener detector.

The component turns on at tokens that open a comment in source code or text,
and at a few Japanese and Korean postpositions. Its activation, as this program
predicts it:
  - `//` and `///` line-comment markers: about 1.1.
  - `*` at the start of a line inside a doc comment (`/** ... */` blocks, licence
    headers, `* @param` lines): about 0.9. The same `*` mid-line (`a * b`) is 0.
  - `#` that starts a comment: an inline `# note` after code (0.7), or a line that
    begins with `#` (0.5). A `#` inside a colour or a macro is not counted.
  - `/*` and `<!--` block-comment openers: about 0.7.
  - the Japanese particle に (ni): about 1.2; words ending in に (的に, 後に): 0.5.
  - the Korean particle 에 (e): 0.9; 로 and 으로: 0.5.
Everything else is 0.
"""
READS = ()

SLASH_COMMENT = {"//", " //", "///", " ///", "//\n", ";//", "){//"}
BLOCK_OPEN = {"/*", " /*", "/**", " /**", "/*\n", " /*\n", "/*\r\n", " /*\r\n", "<!--", " <!--"}
DOC_STAR_EMPTY = {" *\n"}
HASH = {" #", "#"}
PARTICLE = {"に": 1.2, "にも": 1.0, "には": 0.7, "에": 0.9, "로": 0.5, "으로": 0.5}


def line_start(tokens):
    """True if only whitespace or line numbers separate the last token from its line start."""
    for tok in reversed(tokens[:-1][-8:]):
        if "\n" in tok or "\r" in tok:
            return True
        if tok.strip() and not tok.strip().isdigit():
            return False
    return False


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    tok = tokens[-1]
    starts_line = line_start(tokens)
    if tok in SLASH_COMMENT:
        value = 1.1
    elif tok in BLOCK_OPEN:
        value = 0.7
    elif tok == " *" and starts_line:
        value = 0.9
    elif tok in DOC_STAR_EMPTY:
        value = 0.5
    elif tok in HASH:
        value = 0.7 if tok == " #" else (0.5 if starts_line else 0.0)
    elif tok in PARTICLE:
        value = PARTICLE[tok]
    elif len(tok) > 1 and tok.endswith("に"):
        value = 0.5
    else:
        value = 0.0
    return carry, value

