"""Estimate activation from comment punctuation, a few particles, and line quotes.
The program uses visible token cues rather than parsing the surrounding text.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    # A few common Japanese and Korean postpositions also show a positive response.
    particle = token.strip()
    if particle == "に":
        return None, 1.0
    if particle == "에":
        return None, 0.8
    if particle == "로":
        return None, 0.63
    if particle == "으로":
        return None, 0.53

    # A greater-than sign at the start of a line can mark a Markdown quotation.
    if token.strip() == ">" and len(prefix.token_strings) > 1:
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = prefix.token_strings[-2]
        if same_document and previous.endswith(("\n", "\r")):
            return None, 0.18

    # Closing and documentation-comment delimiters have weak responses.
    marker = token.lstrip()
    if marker.startswith("*/"):
        return None, 0.08
    if marker.startswith("/**"):
        return None, 0.05

    # The slash and hash forms start line comments; slash-star opens a block comment.
    if token.lstrip().startswith("//"):
        return None, 1.0
    if token.lstrip().startswith("#"):
        return None, 0.6
    if marker.startswith("/*"):
        return None, 0.6

    # A spaced star is a common decoration inside block-comment documentation.
    if token.startswith(" ") and marker.startswith("*"):
        return None, 0.85
    return None, 0.0

