"""Approximate an escaped-quote response and document-initial offsets.

A token containing a backslash-escaped quote gets a strong positive value.
A space before the quote strengthens it; trailing punctuation weakens it.
At document starts, headings, code openings and capitalized sentence starters
get positive offsets, while chat control markers get negative ones. The role
label immediately after a document-initial chat opener is also negative.
Most other tokens predict zero: weaker word-specific variation is omitted.
"""
READS = ()

# Grammatical words that commonly open a sentence or a question.
DETERMINERS = frozenset("A An The This That These Those All Any Every Some".split())
PRONOUNS = frozenset("I You He She It We They There".split())
QUESTIONS = frozenset("What Which Where When Why How".split())
DECLARATIONS = frozenset(
    "import package using from def function class const let var".split()
)


def escaped_quote(s):
    if '\\"' in s:
        before, after = s.split('\\"', 1)
        if after:
            value = 0.70
            if after.startswith((')', ']', '>')):
                value -= 0.15
            if len(after) > 1:
                value -= 0.20
            return value
        if '"' in before:
            return 0.55
        if before == '.':
            return 0.96
        if before.isspace():
            return 1.48
        if not before:
            return 1.27
        return 1.12
    if "\\'" in s:
        return 0.60
    return None


def initial_token(s):
    word = s.strip()
    if s == '<|im_start|>':
        return -0.37
    if s == '<|endoftext|>':
        return 0.19
    if s.startswith(('<|', '<think', '</think', '<tool', '</tool')):
        return -0.30
    if word == '#':
        return 1.10
    if word.startswith('##'):
        return 0.64
    if word.startswith(('#', '//', '/*', '<?')):
        return 0.46
    if not word:
        return -0.02
    if word.isdigit():
        if word == '2':
            return 0.235
        if word == '0':
            return -0.118
        return 0.0
    if word[0].isalpha():
        if not s[0].isspace():
            if word in DETERMINERS:
                return 0.37
            if word in PRONOUNS:
                return 0.28
            if word in QUESTIONS:
                return 0.44
            if word in DECLARATIONS:
                return 0.42
        elif word in {'the', 'a', 'an'}:
            return -0.12
        if word[0].isupper():
            return 0.15 if s[0].isspace() else 0.19
        if not word.isascii():
            return 0.11
        return 0.08 if s[0].isspace() else 0.03
    if word.startswith(('"', "'", '(', '“')) and not s[0].isspace():
        return 0.35
    if word.startswith(','):
        return -0.12
    if word.startswith('.'):
        return 0.13
    return 0.06


