    'el los las la de del una un en que il le lo gli della di che con per '
    'non da do os uma em não com dos por para les des une'.split()
)
SLAVIC = frozenset(
    'się jest nie jak co je se že pro jsou po ve sa ako pre aj ale '
    'który która oraz przez dla tak też tohto'.split()
)
