    'a': -0.35, 'e': -0.19, 'i': -0.25,
    'o': 0.05, 'u': -0.15, 'y': -0.04,
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0.0, 0.0, 0.0)
    _, previous, english, romance, slavic = carry
    word = s.strip().lower()
