            value += 0.63
    elif t.endswith('я') and not leading:
        value -= 0.21
        if t.endswith('ая'):
            value -= 0.90
        if n <= 3 and t.endswith('ия'):
            value -= 0.36
    elif t.endswith(('a', 'A')):
        penultimate = t[-2:-1].lower()
