                value += 0.83 if leading else 1.05
            elif n == 2:
                value += 1.12
            elif n == 3:
                value += 0.63
            else:
                value += 0.51
            if n in (2, 3) and penultimate == 'i':
                value -= 0.78
        else:
            value += (1.00, 0.64, 0.52, 0.34, 0.06)[min(n, 5) - 1]
            if leading:
                value -= 0.13 if n <= 3 else 0.06
            if t[0].isupper():
                value += 0.10
            if t.lower() == 'alpha':
                value += 0.44
            if any(c.isalpha() and ord(c) > 127 for c in t[:-1]):
                value -= 0.18
            if 2 <= n <= 4:
                vowels = [c for c in t[:-1].lower() if c in 'aeiouy']
