"""A local spelling-boundary heuristic for an o-like vowel.

R/n continuations are usually positive; most consonants are negative.
Vowelless fragments, digraphs and short -er endings strengthen the
negative effect; multiple vowel groups weaken it. Spaces and CamelCase
breaks suppress it. Greek liquids/nasals have positive responses.
Single Katakana/Hangul o-vowel syllables use Unicode pronunciation names.
This models spelling patterns, not token-specific amplitudes or meanings.
"""
import unicodedata as ud

READS = ()
VOWELS = frozenset('aeiouаеиоуыэюяі')
OBSTRUENTS = frozenset('bcdfghjkpqstvxzбвгджзкпстфхцчшщ')
DIGRAPHS = frozenset(('ch', 'ck', 'ct', 'ph', 'sh', 'th', 'sk'))
ONSETS = (
    ('rр', 0.40), ('nн', 0.27), ('ldoлдо', 0.0), ('mм', -0.20),
    ('aeuаеу', -0.13), ('iиі', -0.18),
    ('bfpvgkhqjstбфпвгкхсштщ', -0.39),
    ('cцч', -0.55), ('xzyзж', -0.63),
)


def plain(text):
    return ''.join(c for c in ud.normalize('NFD', text).lower()
                   if not ud.combining(c))


def syllable(character):
    name = ud.name(character, '')
    if name.startswith(('KATAKANA LETTER', 'HANGUL SYLLABLE')):
        return name.split()[-1].lower()
    return ''


def continuation(t):
    c, second = t[0], t[1:2]
    value = next((v for letters, v in ONSETS if c in letters), -0.13)
    if c in 'bfpvgkhqjstcxzyбфпвгкхсштщцчзж':
        groups = sum(ch in VOWELS and (i == 0 or t[i - 1] not in VOWELS)
                     for i, ch in enumerate(t))
        value -= 0.18 * (groups == 0)
        value += 0.19 * (groups > 1)
        value -= 0.17 * (t[:2] in DIGRAPHS)
        value -= 0.33 * (len(t) <= 4 and t.endswith('er'))
    elif c in 'aeuiаеиуі' and second:
        if second in OBSTRUENTS:
            value -= 0.17
        elif second in 'mnrмнр':
            value += 0.18
        elif c in 'iиі' and second in 'lл':
            value -= 0.28
    elif c in 'rр' and second and second in VOWELS:
        value += 0.23
    elif c.isdigit():
        value = -0.16
    value -= 0.16 * (c in 'xzy' and len(t) == 1)
    value -= 0.28 * (c == 'y' and bool(second) and second in VOWELS)
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    state = (doc, token)
    if not previous or not token or not token[0].isalnum():
        return state, 0.0
    p, t = plain(previous), plain(token)
    greek, scale = p.endswith(('ο', 'ω')), 1.0
    if greek:
        scale = 0.55 if p[-1] == 'ω' else 1.0
        if previous[-1].lower() != p[-1]:
            scale *= 0.6
        p = 'o'
    elif len(previous.strip()) == 1:
        roman = syllable(previous.strip())
        if roman.endswith('o') and not roman.endswith('eo'):
            p = 'o'
            if 'HANGUL' in ud.name(previous.strip()):
                scale = 0.65
            t = (syllable(token[0]) or t[0]) + t[1:]
    last_o = max(p.rfind('o'), p.rfind('о'))
    distance = len(p) - last_o - 1 if last_o >= 0 else 99
    strength = (1.0, 0.15, 0.055)[distance] if distance < 3 else 0.0
    if token[0].isupper() and previous[-1].islower():
        strength *= 0.08
    elif previous[-1].isupper() and token[0].islower():
        strength *= 1.4
    value = continuation(t)
    if greek:
        value = next((v for letters, v in (
            ('νρ', 0.95), ('λ', 0.75), ('μ', 0.35)
        ) if t[0] in letters), 0.0)
    return state, float(value * strength * scale)

