import re

READS = ()
INITIAL_DIGITS = (0.539, 0.673, 0.953, 0.648, 0.762,
                  0.815, 0.782, 0.753, 0.717, 0.869)
FIELD_AT_END = re.compile(r'''["']([^"']+)["']:\s*$''')
BARE_NAME = re.compile(r'\bname:\s*$')
SHORT_STRING_COMMA = re.compile(r'''(["'])([^"']{0,24})\1,\s*$''')
# Each pair gives the double-quote and single-quote response, respectively.
FIELD_VALUES = {
    'name': (0.553, 0.50),
    'command': (0.409, 0.22),
    'description': (0.488, 0.22),
}
SYNTAX_MARKERS = {
    '{"': -0.167,
    '<think>': -0.148,
    '</think>': -0.115,
    '://': -0.106,
    '《': 0.190,
}
MOCK_CALL_ASSERTIONS = {
    'toHaveBeenCalled': 0.60,
    'toHaveBeenCalledWith': 0.38,
}


def spaced_quote(before, double):
    which = 0 if double else 1
    if before.endswith(':'):
        field = FIELD_AT_END.search(before)
        if field:
            return FIELD_VALUES.get(field.group(1), (0.35, 0.30))[which]
        if BARE_NAME.search(before):
            return (0.44, 0.22)[which]
        return (0.182, 0.203)[which]
    if before.endswith(('=', '=>')):
        return (0.159, 0.120)[which]
    if before.endswith(','):
        if not double:
            return -0.012
        return 0.051 if SHORT_STRING_COMMA.search(before) else -0.042
    return (0.006, -0.014)[which]


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, initial_run, recent = 0, None, ''
    else:
        _, position, initial_run, recent = carry
    if position == 0 and len(token) == 1 and token in '0123456789':
        initial_run = token
    elif token != initial_run:
        initial_run = None
    before = recent.rstrip()
    if initial_run is not None:
        value = INITIAL_DIGITS[int(initial_run)]
    elif token in (' "', " '"):
        value = spaced_quote(before, token == ' "')
    elif token == ' \\"':
        if before.endswith('='):
            value = 0.176
        elif before.endswith(','):
            value = 0.017
        else:
            value = 0.246 if before.endswith(':') else 0.086
    elif token == ' "/':
        value = 0.108 if before.endswith(':') else -0.09
    elif token == ' {"':
        value = 0.042 if before.endswith(':') else -0.12
    elif position == 0 and token == 'Title':
        value = -0.341
    elif position == 1 and recent == 'Title' and token == ':':
        value = 0.286
    elif position == 0 and token in ('"', "'"):
        value = 0.21
    else:
        value = SYNTAX_MARKERS.get(token, MOCK_CALL_ASSERTIONS.get(token, 0.0))
    return (doc, position + 1, initial_run, (recent + token)[-80:]), value

