            if word.endswith('able'):
                return -1.7
            return -2.3 if word.endswith('ments') else -2.6
        if word.startswith('accompl'):
            return -1.55 if word == 'accomplish' else -1.25
        if word.startswith('attain'):
            return -2.0 if word == 'attainment' else -1.3
        if word.startswith('succeed'):
            return -0.7
    if '取得' in s:
        return -0.95
    if any(w in s for w in ('实现', '實現', '达到', '達到', '达成', '達成')):
        return -0.72
    if any(w in s for w in ('成绩', '成績', '成就')):
        return -1.0
