            value = 0.70
        elif '\n' in previous:
            value = 0.89
        elif previous.strip().isdigit():
            value = 1.03
        else:
            value = 1.0 if previous else 0.83
    elif s.startswith('\t') and s.isspace():
        tabs = len(s) - len(s.lstrip('\t'))
        rest = s[tabs:]
