            value = 0.21 if tabs == 2 else max(-0.25, 0.02-0.08*(tabs-3))
        elif rest == '\n':
            value = 0.47 if tabs == 1 else max(-0.15, 0.3-0.1*tabs)
        elif not rest.strip(' '):
            spaces = len(rest)
            value = max(0.25, 1.0 - 0.028*spaces)
            value += 0.15 if spaces == 3 else 0.0
