"""Layer-0 MLP down-projection, hidden unit 1746 (one rank-one piece of that matrix).

What it responds to, in plain terms:
- Tab indentation. It is strongly positive on a token made only of tabs and spaces that
  starts with a tab (code and markup indented with tabs, e.g. "\\t", "\\t   ", "\\t\\n").
  About 0.9 for a short tab run, lower for long runs of spaces after the tab, about 0.5
  when the run ends in a newline, near zero for runs of three or more tabs, and about
  0.3 when the tab follows spaces (" \\t").
- A non-breaking space (U+00A0) as its own token: positive, a little weaker than a tab.
- Words about achieving a goal are negative. "achieve", "achieved", "achievement" and
  their relatives are strongly negative (about -3). "accomplish", "attain", "succeed",
  and the Chinese 实现 / 取得 / 成就 / 成绩 are moderately negative
  (about -1).
- Everything else, including space indentation and a tab fused with a word ("\\treturn"),
  is about zero.

READS is empty: the program needs only the newest token. It keeps no state.
"""

READS = ()

STRONG = ("achiev",)
MODERATE = ("accomplish", "attain", "succeed", "triumph",
            "достиж", "достиг", "实现", "實現", "取得", "成就", "成绩", "成績", "达到",
            "達成", "达成")


def _is_tab_run(tok):
    # Only tabs, spaces and newlines, containing at least one tab.
    return "\t" in tok and all(c in "\t \n\r" for c in tok)


def _tab_run_value(tok):
    if not tok.startswith("\t"):
        return 0.3  # a tab after spaces, e.g. " \t"
    if tok.count("\t") == 2:
        return 0.2
    if tok.count("\t") > 2:
        return 0.0
    if "\n" in tok:
        return 0.5
    n = len(tok) - 1  # spaces after the tab
    if n <= 8:
        return 0.9
    if n <= 16:
        return 0.6
    return 0.3


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    low = tok.lower()
    if _is_tab_run(tok):
        value = _tab_run_value(tok)
    elif tok == "\xa0":
        value = 0.75
    elif any(s in low for s in STRONG):
        value = -3.0
    elif any(s in low for s in MODERATE):
        value = -1.0
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Recognize sparse whitespace cues and words about accomplishing goals.

Indentation-like tabs and a single nonbreaking space predict positive activity; achievement-
related word pieces predict negative activity. Most other tokens receive zero.
"""

READS = ()

STRONG_ACHIEVEMENT_STEMS = (
    "achiev", "accomplish", "attain", "succeed", "достиж", "取得",
)

OTHER_ACHIEVEMENT_WORDS = (
    "实现", "實現", "成功", "績", "绩",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "\t" in token:
        if token.startswith("\t") and token.count("\t") == 1:
            tail = token[1:]
            if tail and all(char == " " for char in tail):
                return None, max(0.55, 1.0 - 0.03 * len(tail))
            if token == "\t":
                return None, 0.9
            if token == "\t\n":
                return None, 0.45
        if token == " \t":
            return None, 0.3
        return None, 0.2
    if token == "\u00a0":
        return None, 0.75
    word = token.strip().lower()
    if any(stem in word for stem in STRONG_ACHIEVEMENT_STEMS):
        return None, -1.4
    if any(stem in word for stem in OTHER_ACHIEVEMENT_WORDS):
        return None, -0.65
    return None, 0.0

programs.haiku:
"""Layer-0 MLP down_proj component 1747: a token-type detector that is mostly negative.

Its activation is negative on most tokens (mean -1.2), and its size depends mainly on what
kind of token is being read. This program sorts each token into a small, human-readable
class and predicts that class's typical activation:
  - markup tokens such as <|im_start|>, <think>, <tool_call>: strongly negative, about -4;
  - long words (more than 4 letters: "data", "process", "University"): about -1.9;
  - short words (up to 4 letters: "good", "code", "high"): about -1.6;
  - function words (the, a, is, that, not, you, if, has): about -1.35;
  - single letters (x, k, i): about -1.15;
  - prepositions and conjunctions (to, in, for, from, with): about -0.9; " and" about -0.5;
  - " of" about -0.1;
  - punctuation about -0.7, a full stop about -0.4, commas and fullwidth commas 0;
  - whitespace about -0.9;
  - digits: about -1 when they start a number, 0 when they continue one.
Within a document the component is more negative near the start (about -0.4 at the first
token), fading to about 0 after roughly a hundred tokens. The class means were fitted on
1024 training rows, and the position term too. What it leaves out: token-specific
differences inside each class, and rarer words, which are more negative than common ones.
"""

import math
import re
import unicodedata

FUNCTION_WORDS = set(
    "the a an this that these those is are was were be been being am has have had do does did "
    "it its I you he she we they me him her us them my your our their his not can will would "
    "should could may might must if when what which who where how there here all some any each "
    "every no so very".split()
)
PREPOSITIONS_AND_CONJUNCTIONS = set(
    "or but in on at to for from by with as into than about over under between through "
    "after before while because since".split()
)
READS = ()

# Typical activation of each class, fitted on training rows.
CLASS_MEAN = {
    "markup": -4.0,
    "long": -1.9,
    "short": -1.6,
    "function": -1.35,
    "letter": -1.15,
    "connective": -0.9,
    "space": -0.9,
    "punct": -0.7,
    "digit": -1.05,  # a digit that starts a number
    "digit_continues": 0.0,  # a digit right after another digit
    "and": -0.48,
    "period": -0.42,
    "of": -0.11,
    "endoftext": -0.26,
    "comma": -0.01,
    "other": -1.8,
}
POSITION_SLOPE = 0.075  # per unit of log(1 + position in document)
POSITION_OFFSET = -0.40


def word_class(s):
    """The class of one token, from its decoded text."""
    stripped = s.strip()
    if stripped == "":
        return "space"
    if stripped == "<|endoftext|>":
        return "endoftext"
    if re.fullmatch(r"<[^>]*>", stripped):
        return "markup"
    if stripped in {",", "，", "、"}:
        return "comma"
    if s == " of":
        return "of"
    if s == " and":
        return "and"
    if all(unicodedata.category(c).startswith(("P", "S")) for c in stripped):
        return "period" if stripped == "." else "punct"
    if stripped.isdigit():
        return "digit"
    if stripped.isalpha():
        if stripped.lower() in FUNCTION_WORDS:
            return "function"
        if stripped.lower() in PREPOSITIONS_AND_CONJUNCTIONS:
            return "connective"
        if len(stripped) == 1:
            return "letter"
        return "short" if len(stripped) <= 4 else "long"
    return "other"


def step(carry, prefix, upstream):
    """Predict one token's activation from its class, its position, and the token before."""
    t = prefix.position
    docs = prefix.document_ids
    # Where the current document starts, carried along from the previous position.
    if t > 0 and carry is not None and docs[-1] == docs[-2]:
        start = carry
    else:
        start = t
    token = prefix.token_strings[-1]
    cls = word_class(token)
    if cls == "digit" and t > 0 and docs[-1] == docs[-2] and prefix.token_strings[-2].isdigit():
        cls = "digit_continues"
    value = CLASS_MEAN[cls]
    value += POSITION_SLOPE * math.log1p(t - start) + POSITION_OFFSET
    return start, value

programs.luna:
"""Longer letter pieces lean negative; common English link words and symbols do not."""
READS = ()

LINK_WORDS = frozenset(("of", "and", "to", "in", "or", "by", "from", "which"))

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold()
    letters = sum(ch.isalpha() for ch in token)
    if word in {",", "，"}:
        value = 0.0
    elif word in LINK_WORDS and token.startswith(" "):
        value = -0.55
    elif letters:
        value = -0.78 - 0.20 * min(letters, 6)
    elif any(ch.isdigit() for ch in token):
        value = -0.43
    elif token and token.isspace():
        value = -0.93
    else:
        value = -0.50
    return None, float(value)

"""Mark plural-looking word endings, especially a final s in a separate token."""
import re

READS = ()

_NOT_PLURALS = {
    "this", "his", "hers", "its", "ours", "yours", "theirs",
    "was", "has", "does", "yes", "thus", "less", "always",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    match = re.search(r"([a-z]+)$", token)
    ending = match.group(1) if match else ""

    # Sometimes the plural s is its own token; use the immediately preceding stem.
    if token == "s" and len(prefix.token_strings) > 1:
        previous = prefix.token_strings[-2].lower()
        stem = re.search(r"([a-z]+)$", previous)
        if stem and previous.endswith(stem.group(1)):
            ending = stem.group(1) + "s"

    if len(ending) >= 3 and ending.endswith("s") and ending not in _NOT_PLURALS:
        return None, -0.55
    return None, 0.0

programs.sol:
"""A spelling detector dominated by the consonant digraph PH.

Short fragments ending in PH give the largest response, especially when a
vowel comes just before it. PH inside a longer word is weaker. The Greek
letter phi, Cyrillic ef, and file-related words have smaller responses.
A short carry adds a weaker response to the next alphabetic word fragment,
and recognizes PH split between a P-ending token and a following H token.
The Apache name is another small observed trigger. This is a spelling
approximation, not a phonetic parser.
"""

READS = ()


def spelling_value(token):
    word = token.strip()
    lower = word.lower()
    letters = ''.join(c for c in lower if c.isalpha())
    value = 0.002

    if 'ph' in lower and letters.isascii():
        where = lower.rfind('ph')
        before = sum(c.isalpha() for c in lower[:where])
        after = sum(c.isalpha() for c in lower[where + 2:])
        capital = any(c.isupper() for c in word)

        if after == 0:
            value += 4.24 - 0.365 * min(before, 8)
            if before == 0:
                value += 1.72
            elif lower[where - 1] in 'aeiou':
                value += 1.18
                if lower[where - 1] in 'ai':
                    value += 1.50
            value -= 0.74 * capital
            if 'graph' in lower:
                value -= 3.97
            if 'morph' in lower:
                value += 0.83
        else:
            value += 1.90 - 0.167 * min(before, 8)
            value -= 0.065 * min(after, 12) + 0.16 * capital
            if after in (1, 2):
                value += 0.60
            elif after == 3:
                value -= 0.15
            if 'graph' in lower:
                value -= 0.74
            if 'morph' in lower:
                value += 0.35
            if 'phone' in lower:
                value += 0.50
            if 'alpha' in lower:
                value -= 1.31
            if letters == 'phi':
                value -= 0.73
            if letters == 'php':
                value -= 0.42

        if 'phosph' in lower:
            value += 1.70 if after == 0 else 2.14
        if word == 'pH':
            value = 1.97
        else:
            value -= 0.185 * token.startswith(' ')
            value -= 0.84 * token.startswith('.')
        return float(max(0.0, value))

    if 'file' in lower and 'profile' not in lower:
        value += 0.78
    if 'φ' in lower:
        value += 1.82
    if 'ф' in lower:
        value += 0.78 if len(letters) <= 2 else 0.16
    if lower.startswith('.apache'):
        value += 1.87
    elif 'apache' in lower:
        value += 0.59
    return float(value)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, strength = '', 0.0
    else:
        _, previous, strength = carry

    strength_now = spelling_value(token)
    value = strength_now
    lower = token.lower()
    if 'ph' in previous.lower() and previous.strip().isascii():
        # Within-word continuation after a PH-bearing fragment.
        value += strength * (0.142 if token.isalpha() else 0.010)
    if previous.lower().endswith('p') and lower == 'h':
        value += 2.54
    return (doc, token, strength_now), float(value)

programs.haiku:
"""Candidate 4: the 'ph' spelling detector.

The component reads the letters p-h inside a token (phone, photo, graph, and word pieces
such as 'ph', 'aph', 'oph', 'phosph'). It is strongest on short pieces that end in 'ph'
(and especially after a vowel: 'aph', 'iph', 'oph'), weaker on long words, and near zero
on tokens without 'ph'. Greek/Cyrillic phi letters get a moderate value; the chemistry
unit 'pH' and the word 'file' get small fixed values.
"""
READS = ()

PHI_LETTERS = set("φΦфФ")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    low = word.lower()
    if word in PHI_LETTERS:
        return None, 2.0
    if word == "pH":
        return None, 1.5
    if low == "file":
        return None, 0.7
    if "ph" not in low:
        return None, 0.0
    n = len(word)
    if n <= 2:
        value = 4.5
    elif n == 3:
        value = 3.0
    elif n == 4:
        value = 2.2
    elif n <= 6:
        value = 1.4
    else:
        value = 0.9
    if low.endswith("ph"):
        value *= 1.5
        if len(low) > 2 and low[-3] in "aeiou":
            value *= 1.3
    return None, value

programs.sol:
"""A lexical estimate of responses to imported libraries and dotted API names.

Library-qualified members are positive, especially scientific data constructors
and table loading. Ordinary object members are much weaker. Filename suffixes
and domain endings are treated as near-zero exceptions. Small rules cover
import/error words and thinking delimiters. Constants are rounded estimates
from training text,
not a token-ID lookup. Only the last 100 text characters are kept, with a reset
at each document boundary.
"""
import re

READS = ()
SCIENCE = set('np numpy pd pandas gpd geopandas scipy sklearn nltk statsmodels '
              'tf tensorflow torch nn keras jnp jax pm pymc'.split())
VISUAL = set('plt matplotlib sns seaborn ax axes tk tkinter cv2 PIL Image '
             'Gtk GPIO'.split())
STANDARD = set('os sys re math json datetime time shutil subprocess pathlib '
               'tempfile urllib hashlib warnings logging inspect itertools '
               'functools collections pickle csv socket threading asyncio glob '
               'random argparse unittest pytest'.split())
GO = set('fmt strings reflect testing strconv sort bytes errors bufio '
         'filepath ioutil'.split())
WEB = set('requests httpx aiohttp django flask twisted'.split())
DATABASE = set('sqlite3 psycopg2 pymysql sqlalchemy redis'.split())
SUFFIXES = set('py go js ts java c h cpp cc rs rb php html css json yaml yml md txt '
               'xml csv png jpg jpeg svg pdf zip gz exe dll so sh jar hpp jsp htm '
               'com org net edu gov io ru uk de cn co'.split())
FILE_IO = set('read readline readlines readFile readFileSync open close write '
              'flush seek'.split())


def response(token, tail):
    word = token.strip()
    if word == '<think>':
        return -0.24
    if word == '</think>':
        return 0.22
    if word in ('import', 'Import'):
        return 0.51 if token.startswith(' ') else 0.36
    if word in ('error', 'Error', 'errors'):
        return 0.27
    if word in ('err', 'assert'):
        return -0.14
    if word == 'open':
        return 0.23
    if not re.match(r'^\.[A-Za-z_]', token):
        return 0.0

    name = token[1:]
    if name in SUFFIXES or name.startswith('_'):
        return 0.0
    match = re.search(r'([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*)$', tail)
    receiver = match[1] if match else ''
    root = receiver.split('.')[0]
    nested = '.' in receiver

    # Particularly strong, recognizable scientific and graphics API families.
    if root in SCIENCE:
        if root in ('pd', 'pandas') and name == 'read':
            return 4.3
        if root in ('tf', 'tensorflow') and name in ('Variable', 'constant'):
            return 3.84
        if name in ('array', 'DataFrame', 'Series', 'signal', 'placeholder'):
            return 2.42
        if (root in ('nn', 'torch', 'tf', 'tensorflow', 'keras') and
                name in ('Linear', 'Dense', 'Embed', 'Embedding')):
            return 3.51
        if root in ('scipy', 'sklearn', 'nltk'):
            return 2.27
        return 0.99 if nested else 1.61
    if root == 'pygame':
        if receiver.endswith('.time') and name == 'Clock':
            return 3.82
        return 1.75 if nested else 2.39
    if root in ('boto', 'boto3'):
        return 3.46
    if root in VISUAL:
        return 0.99 if nested else 1.7
    if root in WEB:
        if nested:
            return 0.99
        return 2.35 if root in ('requests', 'httpx', 'aiohttp') else 1.56
    if root in STANDARD | DATABASE:
        if receiver == 'os' and name == 'path':
            return 1.76
        if nested:
            return 0.99
        if name in ('run', 'time', 'Error', 'warn', 'error', 'new'):
            return 2.09
        return 1.19

    # Other languages and weaker ordinary member names.
    if root in GO:
        if root == 'fmt':
            return 0.88 if name in ('Sprintf', 'Fprintf', 'Errorf') else 0.18
        return 0.74
    if root in ('java', 'javax', 'android'):
        return 0.87 if nested else 0.62
    if root == 'org' and nested:
        return 0.42
    if root in ('self', 'this', 'super'):
        return 0.18 if root == 'self' else 0.0
    if receiver == 'go' and name in ('mod', 'sum', 'work'):
        return 0.82 if name == 'mod' else 0.28
    if receiver == 'console' or len(name) == 1:
        return 0.15
    if (name.startswith(('get', 'set', 'put', 'add')) and len(name) > 3 and
            name[3].isupper()):
        return 0.07
    if name in FILE_IO:
        return 0.64
    return 0.4 if name[:1].isupper() else 0.27


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, (tail + token)[-100:]), float(response(token, tail))

programs.haiku:
"""Stock-phrase head nouns.

Some nouns are the head of a fixed connective or prepositional phrase: "in case",
"in order (to)", "in addition", "in terms of", "in fact", "of course", "on behalf of",
"this case", "with respect to". This component is strongly negative on that head noun.
The size depends on the word just before it: after "in" the dip is large for almost any
such noun ("in case", "in order", "in addition" are the strongest); after "this / that /
any" or "the" it is large only for a narrower set ("this case", "the event"); after
"on / by / with / for" for a few ("on behalf", "with respect"). A function word right
after a few of these nouns ("case [of]", "order [to]") is mildly negative too.
Everywhere else it predicts 0, since the component is near zero on ordinary text.
"""
READS = ()

# After "in": the strong idiom heads, then the weaker ones.
IN_STRONG = {"case", "cases", "order", "addition", "reality", "principle", "theory", "contrast",
    "comparison", "regard", "regards", "spite", "turn", "general", "view", "effect", "terms",
    "accordance", "response", "respect", "advance", "conjunction", "connection", "vitro",
    "virtue", "behalf"}
IN_WEAK = {"place", "light", "fact", "practice", "conclusion", "relation", "result", "range",
    "favor", "favour", "time", "front", "line", "part", "mind", "nature", "base", "form",
    "future", "past", "purpose", "means", "sake", "reason", "instance", "occasion"}
DET_NOUNS = {"case", "cases", "circumstances", "reason", "context", "occasion", "instance",
    "event", "absence", "time", "point", "way", "hand", "order", "sense", "purpose"}
ART_NOUNS = {"case", "cases", "event", "absence", "presence", "basis", "context",
    "circumstances", "purposes", "course", "form", "past", "time", "range"}
PREP_NOUNS = {"behalf", "virtue", "respect", "regard", "account", "contrast", "point", "means"}
DETERMINERS = {"this", "that", "any", "which", "such", "our", "each", "some", "every", "same",
    "other", "all", "most"}
ARTICLES = {"the", "a", "an"}
PREPOSITIONS = {"on", "at", "by", "into", "with", "for"}
# Nouns whose "of / to / with" complement is itself a fixed-phrase cue.
COMPLEMENT_NOUNS = {"case", "cases", "course", "order", "addition", "terms", "view", "form",
    "spite", "behalf", "event"}
COMPLEMENT_WORDS = {"of", "to", "with"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    if len(toks) < 2 or docs[-1] != docs[-2]:
        return None, 0.0
    prev = toks[-2].strip().lower()
    cur = toks[-1].strip().lower()
    if prev == "in":
        if cur in IN_STRONG:
            return None, -2.7
        if cur in IN_WEAK:
            return None, -1.5
    if prev == "of" and cur == "course":
        return None, -2.0
    if prev in DETERMINERS and cur in DET_NOUNS:
        return None, -1.5
    if prev in ARTICLES and cur in ART_NOUNS:
        return None, -1.0
    if prev in PREPOSITIONS and cur in PREP_NOUNS:
        return None, -1.2
    if prev in COMPLEMENT_NOUNS and cur in COMPLEMENT_WORDS:
        return None, -0.7
    return None, 0.0

programs.sol:
"""English verb-particle phrases produce a negative response, especially
'end up', 'show up', 'slow down', and 'turn out'. Literal motion such as
'go up' is weak. Related verb inflections share strengths, and an object
pronoun can separate the verb and particle. Attached fragments are weaker.
Chinese upward/downward resultative compounds receive a small negative value.
"""
READS = ()

# Familiar phrasal-verb families, grouped by approximate response strength.
FAMILIES = {
    'up': (
        (-7.2, 'end wind'), (-5.5, 'show wake warm'),
        (-3.8, 'mess heat grow'), (-3.3, 'clean sign blow turn speed'),
        (-3.3, 'team pair line wrap screw'),
        (-2.5, 'set open sum pop match light hook start'),
        (-1.8, 'follow back catch stir round tie fill'),
        (-1.0, 'pick break give bring come make build'),
    ),
    'down': (
        (-4.8, 'slow cool calm wind'), (-3.2, 'shut track turn'),
        (-2.5, 'sit narrow settle close note'),
        (-1.8, 'break lay boil lie strip upside round'),
        (-0.9, 'set write cut come bring'),
    ),
    'out': (
        (-3.3, 'turn'), (-2.7, 'figure'), (-2.1, 'filter stand wipe single'),
        (-1.5, 'find check carry point cancel sort rule lay'),
        (-1.0, 'set work cut print fill spread hang start'),
        (-0.65, 'come give'),
    ),
    'off': (
        (-2.4, 'show turn'), (-1.8, 'cool spin pay shut'),
        (-1.4, 'switch start finish'), (-1.0, 'set cut trade round kick top'),
    ),
    'in': ((-0.6, 'result interest'),),
}
DEFAULT = {'up': -0.3, 'out': -0.25, 'down': -0.35, 'off': -0.6}
IRREGULAR = dict(zip(
    'woke woken grew grown shown blew blown made caught gave given came '
    'sat laid lying broke broken written wrote found paid wound stood lit'.split(),
    'wake wake grow grow show blow blow make catch give give come '
    'sit lay lie break break write write find pay wind stand light'.split()))
VERBS = {v for rows in FAMILIES.values() for _, words in rows for v in words.split()}
OBJECTS = set('it them him her this that me us you'.split())
WEAK = set('go going goes went get got getting move moving walk walking '
           'and or of for to by with a the is are was were be been'.split())


def lemma(word):
    if word in IRREGULAR:
        return IRREGULAR[word]
    if word not in VERBS:
        for suffix in ('ing', 'ied', 'ies', 'ed', 'es', 's'):
            if word.endswith(suffix):
                root = word[:-len(suffix)]
                for candidate in (root, root + 'e', root[:-1], root + 'y'):
                    if candidate in VERBS:
                        return candidate
    return word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, earlier = '', ''
    else:
        _, previous, earlier = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    hyphenated = word.startswith('-')
    word = word[1:] if hyphenated else word
    surface = earlier if previous in OBJECTS else previous
    verb = lemma(surface)
    value = DEFAULT.get(word, 0.0)
    for strength, words in FAMILIES.get(word, ()):
        if verb in words.split():
            value = strength
            break
    if word in {'up', 'down', 'out'} and (not verb or verb in WEAK):
        value = 0.0
    if hyphenated:
        value *= 0.85
    elif not token.startswith(' '):
        value *= 0.35
    if word in {'起来', '起來', '下来', '下來', '了下来'}:
        value = -1.0
    return (doc, word, previous), float(value)

"""A lexical detector for ell: strong negative values on short ell pieces,
then tell, bell, cell, sell, shell and their relatives. Longer ell spellings
are weaker. A few synonyms and translations also respond. Casing and word
boundaries distinguish names, pronouns and fragments; LaTeX \\ell is weaker.
Other tokens get zero. The strengths are corpus estimates, not model weights.
