READS = ()

# Whole stems and their ordinary inflections: one spelling family, not token ids.
ELL_WORDS = {
    'tell': 5.2, 'tells': 3.8, 'telling': 4.1, 'told': 3.0,
    'sell': 3.2, 'sells': 2.4, 'selling': 2.2, 'sold': 1.0,
    'seller': 2.4, 'sellers': 2.5,
    'cell': 2.6, 'cells': 1.9, 'cellular': 1.1, 'cellul': 1.5,
    'bell': 4.2, 'bells': 3.0,
    'shell': 3.1, 'shells': 2.6,
    'well': 1.2, 'wells': 1.4,
    'fell': 1.1, 'fellow': 0.95, 'fellows': 1.0,
    'hell': 2.1, 'hello': 1.0,
    'dell': 2.9, 'nell': 3.0, 'pell': 4.0, 'mell': 2.4,
    'spell': 1.6, 'spells': 1.2, 'spelling': 0.8, 'spelled': 0.9,
    'smell': 0.7, 'smells': 0.45,
    'panel': 0.8, 'panels': 0.9,
    'yellow': 0.08, 'dwell': 0.1,
}

# Suffix fragments of the very short sequence ell.
ELL_FRAGMENTS = {
    'ell': 5.1, 'ella': 3.75, 'elle': 2.15, 'elli': 2.25,
    'ells': 3.4, 'ellar': 3.8, 'eller': 2.6, 'ellers': 2.7,
    'elling': 2.2, 'ellen': 2.3, 'ello': 2.55, 'elled': 2.3,
    'elly': 1.8, 'ellt': 1.6,
}

# Translations of tell, cell, shell, sell, well, and the letter ell.
ELL_TRANSLATIONS = {
    '告诉': 3.2, '告訴': 3.0,
    '细胞': 1.5, '細胞': 1.5, 'セル': 1.2,
    '壳': 2.0, '殼': 2.0, '贝壳': 2.4, '貝殼': 2.4,
    '卖': 1.1, '賣': 1.1, '销售': 0.9, '銷售': 0.9, '売': 0.7,
    '井': 1.0, 'ℓ': 1.8, 'ベル': 1.0,
}

TELL_SYNONYMS = {
    'inform', 'informed', 'informing', 'informs',
    'remind', 'reminded', 'reminding', 'reminds',
}


def strength(token):
    word = token.strip().lstrip('_-.\'"<“’')
    low = word.lower()
    boundary = token[:1].isspace() or token[:1] in {"'", '’'}
    if low == 'll' and token.lstrip().startswith(("'", '’')):
        return 0.04
    if word in ELL_TRANSLATIONS:
        return ELL_TRANSLATIONS[word]
    if word.startswith(('告诉', '告訴')):
        return 1.2
    if low in ELL_WORDS:
        value = ELL_WORDS[low]
        if low == 'well':
            value = 1.12 if boundary and word.islower() else 1.7
        elif word[:1].isupper():
            if low in {'tell', 'sell', 'shell'}:
                value += 0.8
            elif low in {'bell', 'cell', 'cells'} and boundary:
                value += 0.5
            elif low == 'fell':
                value = 3.1
        return value
    if low in ELL_FRAGMENTS:
        value = ELL_FRAGMENTS[low]
        if boundary and low in {'ella', 'elle', 'ello', 'eller'}:
            value = 1.05
        if low == 'ellen' and word[:1].isupper():
            value = 2.9
        if low == 'ell' and word[:1].isupper():
            value = 4.2 if word.isupper() else 3.0
        return value
    if low.startswith('stell'):
        return 4.3 / (1.0 + 0.6 * (len(low) - 5))
    if low in TELL_SYNONYMS:
        return 1.05
    if low in {'else', 'elif'}:
        return 0.55
    if 'ell' in low:
        # Bare ell-initial pieces are stronger than long, complete words.
        if low.startswith('ell') and not boundary:
            return 1.8
        value = 2.5 / max(1.0, len(low) - 3.0)
        if word.istitle() and len(low) <= 7:
            value *= 1.5
        return value
    if low == 'll':
        return 1.6 if word.isupper() else 1.1
    if low in {'lla', 'lle', 'lli', 'ller', 'llen'}:
        return 0.9
    if low in {'äll', 'yll'}:
        return 1.0
    if low in {'tel', 'pel'}:
        return 1.0
    if low == 'del':
        return 0.35
    if low == 'el' and word[:1].isupper() and boundary:
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = strength(token)
    if token.lower() == 'ell' and len(prefix.token_strings) > 1:
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        if same_document and prefix.token_strings[-2].endswith('\\'):
            value = 3.5  # The LaTeX command \ell, rather than a word fragment.
    return None, -float(value)

