"""Fires on a family of words that introduce a restatement ("that is", "namely",
"i.e."), a focus or hedge ("just", "even", "simply", "perhaps"), or immediacy
("immediately"), plus the Chinese particles 就 / 即 / 便, and the end-of-text token.

Values are typical activations for each class, in the component's own units.
"""
READS = ()

EOT = "<|endoftext|>"
HEDGE = {"just", "even", "perhaps", "maybe", "simply", "merely", "essentially",
         "basically", "possibly", "literally", "namely"}
IMMEDIATE = {"immediately", "immediate", "instant", "instantly", "promptly",
             "shortly", "马上", "立即", "即刻", "尽快", "すぐ", "すぐに"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if tok == EOT:
        v = 1.7
    elif tok == ".e" and prev == "i":
        v = 2.7                       # "i.e."
    elif tok == ".g" and prev == "e":
        v = 0.9                       # "e.g."
    elif "即" in tok:
        v = 3.0
    elif "就是" in tok or tok == "namely":
        v = 2.4
    elif "就" in tok:
        v = 1.5
    elif "便" in tok or tok == "甚至":
        v = 1.0
    elif tok in HEDGE:
        v = 1.1
    elif tok in IMMEDIATE:
        v = 1.0
    else:
        v = 0.0
    return carry, float(v)

