    elif lower in {'女', '女子', '们'}:
        value = 0.45
    elif lower == 'mice':
        value = 1.1
    elif lower in {'mem', 'memo', 'memor', 'memory', 'memories'}:
        value = 0.9 if lower == 'mem' else 0.65
    elif lower.startswith(('menu', 'enumer')) or lower == 'enum':
