programs.haiku:
"""layers.0.mlp.down_proj:1757 -- a "comparison complement" detector.

This component writes a negative signal into the residual stream on the function word
that completes a comparison or relation phrase, and is near zero everywhere else:

    "is equal to"  "similar to"  "close to"  "adjacent to"   -> strongly negative on "to"
    "greater than" "less than"   "larger than" "other than"    -> strongly negative on "than"
    "related to"   "compared to" "up to"  "prior to"          -> moderately negative on "to"
    "the same as"                                             -> negative on "as"
    "such that"                                               -> mildly negative on "that"
    "different from" "away from"                              -> mildly negative on "from"
    "divided by" "followed by"                                -> mildly negative on "by"
    "more than"                                               -> slightly negative on "than"

Everywhere else (including "to" in infinitives such as "wanted to") it predicts 0.
The rule looks at the whole word before the preposition (the last letters of the
preceding text), so split words like "pursuant" or "isomorphic" still count.
"""
import re

READS = ()

# The word before "to" that makes the phrase a comparison of equality or similarity.
EQUAL = {"equal", "equals", "equivalent", "identical", "comparable"}
SIMILAR = {"similar", "close", "closer", "closest", "adjacent", "near", "nearest",
           "proportional", "parallel", "perpendicular", "opposite", "superior"}
CORRESPOND = {"corresponding", "corresponds", "correspond"}
# Looser relations that also take "to" ("related to", "compared to", "up to").
RELATED = {"related", "relating", "relates", "relative", "connected", "compared", "prior",
           "next", "subsequent", "pertaining", "attached", "linked", "subject", "subjected",
           "respect", "pursuant", "up", "limited", "open", "listen", "listening", "opposed"}
# Comparatives that take "than".
COMPARATIVE = {"greater", "less", "higher", "lower", "larger", "smaller", "bigger", "shorter",
               "longer", "later", "earlier", "fewer", "younger", "better", "other"}
DIFFERENT = {"different", "differ", "away", "apart"}
DIVIDED = {"followed", "divided", "multiplied", "divisible", "sides"}


def step(carry, prefix, upstream):
    """Activation at the newest token: negative if it is a comparison/relation preposition."""
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur = prefix.token_strings[-1].strip()
    before = "".join(prefix.token_strings[-4:-1])
    found = re.search(r"([A-Za-z]+)\s*$", before)
    prev = found.group(1).lower() if found else ""
    if cur == "to":
        if prev in EQUAL:
            return carry, -5.5
        if prev in SIMILAR:
            return carry, -4.0
        if prev in CORRESPOND:
            return carry, -2.8
        if prev in RELATED:
            return carry, -1.8
    if cur == "than":
        if prev in COMPARATIVE:
            return carry, -3.5
        if prev == "more":
            return carry, -0.75
    if cur == "as" and prev == "same":
        return carry, -2.8
    if cur == "that" and prev == "such":
        return carry, -1.3
    if cur == "from" and prev in DIFFERENT:
        return carry, -1.5
    if cur == "by" and prev in DIVIDED:
        return carry, -1.3
    return carry, 0.0

