"""A lexical contrast: adhesive/manufactured materials versus authority.

Recognized material names are negative, particularly glue and rubber;
'authority' and 'authorities' are positive. Chinese glue is less negative
in the compounds for colloid (溶胶) and gel (凝胶/凝膠). Other Chinese
material morphemes have separate strengths. Matching is lexical, not a
general semantic detector; unmatched tokens are zero. Context is used only
to recognize those glue compounds, within the current document.
"""

READS = ()

# Material classes, from strongly adhesive substances to weaker media.
MATERIALS = (
    (-2.1, {'rubber'}),
    (-1.5, {'resin', 'adhesive', 'epoxy', 'silicone'}),
    (-1.3, {'glue', 'foam'}),
    (-1.1, {'wax', 'tape', 'latex', 'nylon'}),
    (-0.85, {'membrane', 'cement', 'cable', 'tubing', 'vacuum', 'gum', 'pulp'}),
    (-0.65, {'plastic', 'polymer', 'fiber', 'vinyl', 'asbestos'}),
    (-0.5, {'paper', 'glass', 'gel', 'tube', 'laser', 'cotton', 'soap'}),
)
MATERIAL_VALUES = {w: v for v, words in MATERIALS for w in words}
CHINESE = (
    (-3.3, {'橡胶'}),
    (-2.0, {'膜', '树脂'}),
    (-1.8, {'漆'}),
    (-1.1, {'蜡', '膏', '浆', '橡', '塑', '塑料', '泡沫', '玻璃', '薄膜'}),
    (-0.8, {'乳', '棉', '水泥', '电缆', '焊'}),
    (-0.6, {'铜', '墨', '纸', '奶', '纤维'}),
)
CHINESE_VALUES = {w: v for v, words in CHINESE for w in words}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    if word in {'胶', '膠'}:
        previous = ''
        if (prefix.position > 0 and
                prefix.document_ids[-1] == prefix.document_ids[-2]):
            previous = prefix.token_strings[-2]
        if previous.endswith('凝'):
            value = -1.3
        elif previous.endswith('溶'):
            value = -2.7
        else:
            value = -4.8 if word == '胶' else -4.55
    elif word in CHINESE_VALUES:
        value = CHINESE_VALUES[word]
    elif lower == 'authority':
        value = 2.5 if word == 'Authority' else 2.1
        if not token.startswith(' '):
            value *= 0.7
    elif lower == 'authorities':
        value = 1.9 if token.startswith(' ') else 1.4
    elif lower in {'authoritative', 'ority'} or word in {'权威', '權威'}:
        value = 0.9
    elif word in {'官方', '方向'} or lower in {'council', 'direction'}:
        value = 0.4
    elif token.startswith(' ') and lower in MATERIAL_VALUES:
        value = MATERIAL_VALUES[lower]
        if word == 'Rubber':
            value = -2.3
        elif word[0].isupper():
            value *= 0.8
    elif lower in {'tape', 'latex'}:
        value = MATERIAL_VALUES[lower] * 0.7
    else:
        value = 0.0
    return None, value

