"""Component layers.0.mlp.down_proj:1758: a "glue and synthetic materials" detector with
an opposite response to "authority" words.

The component reads only the current token (no context is needed; its value follows the
word alone). It is a token-level detector with four levels:

1. Strongly negative (about -4.4) on the Chinese character 胶 (glue / rubber / gum), and
   on 橡胶 (rubber) and 塑胶 (plastic).
2. Negative (about -1.3) on adhesives and sticky or coating materials: rubber, glue,
   glued, adhesive, resin, silicone, foam, wax, gum, tape, and 膜 (film), 漆 (lacquer),
   蜡 (wax), 浆 (paste).
3. Mildly negative (about -0.45) on other manufactured or industrial substances: plastic,
   polymer, membrane, paper, glass, steel, cement, tube, cable, rope, fiber, coating,
   insulation, vinyl, nylon, asbestos, foil, soap, cream, gel, jelly, grease, and their
   Chinese equivalents (电缆 cable, 玻璃 glass, 水泥 cement, 铜 copper, 纸 paper).
4. Positive on authority: "authority" (about +2.1, the strongest positive), "authorities",
   and 权威 (authority), with "authoritative" a little lower. Weaker positive (about +0.25)
   on governance and official-body words: author, direction, council, affairs, official,
   jurisdiction, agency, institution, enterprise, assembly, authorized, 官方, 方向.
Everything else predicts 0.

Why this shape: the activation is dominated by a few tokens (胶 and "authority"), and
the rest is a long tail of small values with the same sign pattern (materials negative,
governance positive). The program captures the strong levels and the broad sign pattern.
"""

READS = ()

GLUE_CHARS = {"胶": -4.4, "橡胶": -4.4, "塑胶": -3.0}

ADHESIVE = {
    "rubber", "glue", "glued", "adhesive", "resin", "silicone", "foam", "wax", "gum",
    "gums", "tape", "tapes", "taped",
}
ADHESIVE_CHARS = {"膜": -1.9, "漆": -1.8, "蜡": -1.6, "浆": -1.2}

MATERIAL = {
    "plastic", "plastics", "polymer", "membrane", "membranes", "paper", "glass", "steel",
    "cement", "tube", "tubes", "tubing", "cable", "cables", "rope", "ropes", "fiber",
    "fibers", "fibre", "coating", "coated", "coatings", "insulation", "vinyl", "acrylic",
    "polyester", "nylon", "asbestos", "foil", "laminate", "soap", "cotton", "asphalt",
    "tar", "gel", "cream", "jelly", "grease", "laser", "vacuum", "pvc", "eps",
}
MATERIAL_CHARS = {"电缆": -0.9, "玻璃": -0.9, "水泥": -0.9, "铜": -0.7, "纸": -0.6,
                  "混凝土": -0.3}

AUTHORITY = {"authority": 2.1, "authorities": 2.0, "authoritative": 0.9,
             "authoritarian": 0.9}
AUTHORITY_CHARS = {"权威": 0.9}

GOVERNANCE = {
    "author", "authors", "direction", "directions", "council", "affairs", "official",
    "officials", "jurisdiction", "agencies", "agency", "institutions", "enterprise",
    "assembly", "authorized", "authorization",
}
GOVERNANCE_CHARS = {"官方": 0.5, "方向": 0.5}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lower()

    if text in GLUE_CHARS:
        return carry, float(GLUE_CHARS[text])
    if text in ADHESIVE_CHARS:
        return carry, float(ADHESIVE_CHARS[text])
    if text in MATERIAL_CHARS:
        return carry, float(MATERIAL_CHARS[text])
    if text in AUTHORITY_CHARS:
        return carry, float(AUTHORITY_CHARS[text])
    if text in GOVERNANCE_CHARS:
        return carry, float(GOVERNANCE_CHARS[text])
    if word in AUTHORITY:
        return carry, float(AUTHORITY[word])
    if word in ADHESIVE:
        return carry, -1.3
    if word in MATERIAL:
        return carry, -0.45
    if word in GOVERNANCE:
        return carry, 0.25
    return carry, 0.0

