"""A negative pulse on short continuations after a W-bearing token.

W/w at the preceding token's end gives the largest response, weakened by
long words, long continuations, mixed case, or intervening letters. Another
W in the current token suppresses the pulse. Cyrillic в and Thai ว give
weaker analogues. State is only the preceding token in the same document.
"""
import math
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if not token:
        return (doc, token), value

    first = token[0]
    letters = first.isalpha() or unicodedata.category(first).startswith('M')
    letters = letters or first == '\ufffd'
    distance = len(previous) - max(previous.rfind('w'), previous.rfind('W')) - 1
    has_w = 0 <= distance <= 2 and ('w' in previous or 'W' in previous)
    if has_w:
        if letters:
            amplitude = (1.96 if previous.endswith('W') else 1.55)
            if distance == 1:
                amplitude = 0.38
            elif distance == 2:
                amplitude = 0.21
            if 'w' in token.lower():
                scale = 0.0
            elif token.isupper():
                scale = 0.80
            elif token.istitle():
                scale = 0.55
            elif token.islower():
                scale = 1.0
            else:
                scale = 0.15
            fade = 0.275 * (len(token) - 1)
            fade += 0.55 * max(0, len(previous.strip()) - 3)
            value = -amplitude * scale * math.exp(-fade)
        elif distance == 0:
            if first.isdigit():
                value = -0.59
            elif first.isspace():
                value = -0.057
            elif first in "-/'":
                value = -0.19
            else:
                value = -0.039
    elif previous.endswith(('в', 'В')):
        if letters:
            fade = 0.45 * (len(token) - 1)
            fade += 1.5 * max(0, len(previous.strip()) - 3)
            value = -0.465 * math.exp(-fade)
        elif first.isspace():
            value = -0.033
    elif previous.endswith('ว'):
        value = -0.28

    if token.strip() in ('w', 'W'):
        value -= 0.09
    return (doc, token), float(value)

"""A multilingual question/exclamation signal, predicted from orthography.

Question and exclamation marks usually produce negative predictions, with
fullwidth forms strongest in East Asian text. Line breaks, closing quotes
and repeated signs change their strength. The preceding token's case, spacing and number status, the scripts
in the last twelve tokens, and proximity to the document start adjust it.
A few grammatical question particles are negative too. Other tokens get a
small baseline. The history resets at document boundaries.
"""
READS = ()


def letter_scripts(text):
    non_ascii = any(c.isalpha() and ord(c) > 127 for c in text)
    east_asian = any(
        '\u2e80' <= c <= '\u9fff' or '\uac00' <= c <= '\ud7af'
        for c in text if c.isalpha()
    )
    return int(non_ascii), int(east_asian)


def punctuation_base(text):
    s = text.strip()
    line = min(text.count('\n'), 2)
    if any(c in s for c in '=<>/#') or any(c.isalnum() for c in s):
        return None
    if '？' in s:
        return (-1.62 if len(s) == 1 else -0.53, -1.11, -0.55)[line]
    if '！' in s:
        return (-0.63 if len(s) == 1 else 0.06, -0.12, -0.10)[line]
    if '؟' in s:
        return -1.57
    if not any(c in s for c in '?!'):
        return None
    if s.startswith(('(!', '(?')):
        return -0.10
    if '?' in s and '!' in s:
        return -0.79
    if s.count('?') > 1:
        return 0.08
    if s.count('!') > 1:
        return (-0.24, -0.13, -0.14)[line]
    if s.startswith('!['):
        return -0.25
    if s.startswith('!('):
        return -0.52
    question = '?' in s
    if s.startswith(('?"', "?'", '?”')):
        return (-0.90, -0.69, -0.50)[line]
    if s.startswith(('!"', "!'", '!”')):
        return (-0.61, -0.51, -0.41)[line]
    if '.' in s:
        return -0.16 if question else -0.11
    return (-0.52, -0.39, -0.31)[line] if question else (
        -0.32, -0.21, -0.33
    )[line]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', ())
    _, position, previous, history = carry
    text = prefix.token_strings[-1]
    s = text.strip()
    value = punctuation_base(text)
    if value is not None:
        word = previous.strip()
        recent_non_ascii = sum(a for a, b in history) / max(len(history), 1)
        recent_east_asian = sum(b for a, b in history) / max(len(history), 1)
        correction = 0.04 if text.startswith(' ') else 0.0
        correction += 0.23 if word.isdigit() else 0.0
        correction -= 0.26 if word[:1].isupper() else 0.0
        correction -= 0.17 if (
            previous and not previous.startswith(' ') and word[-1:].isalpha()
        ) else 0.0
        correction -= 0.24 * letter_scripts(previous)[0]
        correction -= 0.22 * recent_non_ascii + 0.85 * recent_east_asian
        correction -= 0.42 * 32 / (32 + position)
        value += correction * (0.55 if '\n' in text else 1.0)
        if s == '?' and position == 0:
            value = -0.06
        if s == '!' and word.isdigit():  # factorial, rather than an exclamation
            value = 0.02
    else:
        value = 0.002
        if s.endswith(('吗', '嗎')):
            value = -1.15 if len(s) > 1 else -0.82
        elif s == '呢':
            value = -0.44
        elif s in ('么', '麼'):
            value = -0.25
        elif s == '了吧':
            value = -0.80
        elif s == 'か':
            value = -0.26
        elif s in ('ですか', 'でしょうか', 'のか'):
            value = -0.60
        elif s in ('なのか', 'のでしょうか'):
            value = -1.10
        elif s == 'ли' and text.startswith(' '):
            value = -0.43
    history = (history + (letter_scripts(text),))[-12:]
    return (doc, position + 1, text, history), float(value)

