def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    while token and token[-1] in "\"'’”)]}」』》】":
        token = token[:-1].rstrip()
    if not token:
        return carry, 0.0

    mark = token[-1]
    if mark == "吗":
        return carry, -0.8
    name = unicodedata.name(mark, "")
    if "QUESTION MARK" in name:
        if "FULLWIDTH" in name:
