programs.sol:
"""Approximate negative pulses at the beginning of a new line.

The strongest triggers are code fences, diff hunks and closing markup tags.
Page-navigation, post metadata and section labels also trigger. Indentation
weakens structural-marker pulses. Most ordinary text is predicted as zero.
These rules summarize observed training responses, not a complete markup parser.
"""

READS = ()

STRONG_LABELS = frozenset('View Related Answer Advertisement Advertisements'.split())
WEB_LABELS = frozenset('Follow Posts Posted Published Download Share Show '
                       'Home Previous Question More'.split())
METADATA_AND_LINKS = frozenset('Joined Join Author Copyright Comment Updated Views '
                              'Subjects Full Click'.split())
HEADINGS = frozenset('Title Category References Explanation Description Chapter '
                     'Abstract Subject Topic Worksheet Lesson'.split())
LINE_SIGNS = {
    '+': -0.21,
    '+++': -0.67,
    '\\': -0.33,
    '*': 0.16,
    '©': -1.01,
    '#define': -0.44,
    '#include': -0.27,
}
NAVIGATION = frozenset('Last Next See Back Recent Latest Watch'.split())


def estimate(s, newline, indent, afterticks):
    x = s.strip()
    ticks = bool(x) and set(x) == {'`'}
    if not newline:
        if x == '</':
            return -0.65 if indent else -0.15
        if ticks and len(x) >= 2:
            if indent or afterticks:
                return -0.40
            return -0.23 if s[0].isspace() else 0.20
        if x == 'View':
            return -0.35
        return 0.0
    if ticks:
        value = -0.16 if len(x) == 1 else (-1.83 if len(x) == 2 else -1.46)
    elif x == '@@':
        value = -2.52
    elif x == '</':
        value = -2.04
    elif x == '$$':
        value = -0.84
    elif x and set(x) == {'>'}:
        value = -0.19 if '\n' in s else -0.62
    elif len(x) >= 3 and set(x) <= set('-=_/'):
        value = -0.55 if len(x) > 32 else -0.80
        if '\n' in s:
            value *= 0.35
        if x.startswith('///') and len(x) <= 4:
            value = -0.10
    elif x.startswith('/*') or x.startswith('*/') or x == '"""':
        value = -0.25 if '\n' in s else -0.60
    elif x in STRONG_LABELS:
        value = -1.75
    elif x in WEB_LABELS:
        value = -1.10
    elif x in METADATA_AND_LINKS or x == 'README':
        value = -0.75
    elif x in HEADINGS or x in NAVIGATION:
        value = -0.37
    elif x in LINE_SIGNS:
        value = LINE_SIGNS[x]
    elif x.startswith('}'):
        value = -0.47 if x.endswith(';') else (-0.21 if '\n' in s else -0.62)
    elif x in {'<', '【', '「', '«'}:
        value = -0.30
    elif x.startswith('#') and x[1:] in {'endif', 'else', 'ifdef', 'ifndef'}:
        value = -1.35 if x == '#endif' else -0.77
    else:
        return 0.0
    return float(value * (0.65 if s[0].isspace() else 1.0))


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    newline, indent, afterticks = (False, False, False) if first else carry[1:]
    value = 0.0 if first else estimate(s, newline, indent, afterticks)
    line_open = newline or indent
    if '\n' in s:
        line_open = not s.rsplit('\n', 1)[1].strip()
    elif s.strip():
        line_open = False
    x = s.strip()
    # Remember only boundary/indentation and backtick context, not full text.
    state = (doc, s.endswith('\n'), line_open, bool(x) and set(x) == {'`'})
    return state, float(value)

programs.haiku:
"""Negative response at the start of a line to block-level markup: code fences, rules, diff hunks, closing tags, and page-furniture words."""

READS = ()

FENCE = {"```", "``", "$$", "@@", "</", "~~"}
RULE_CHARS = set("=-/*")
HTML_OPEN = {">", "<"}
PAGE = {
    "Posts", "Posted", "posted", "Joined", "Follow", "Share", "Related", "Full", "More",
    "README", "Views", "View", "Forum", "Category", "Topic", "Topics", "Answer", "Advertisement",
    "Copyright", "Author", "Tags", "Comment", "Continue", "Loading", "Show", "Hide", "Best",
    "Last", "Question", "Article", "©",
}
DATES = {
    "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
    "January", "February", "March", "April", "June", "July", "August", "September",
    "October", "November", "December",
}


def is_rule(tok):
    return len(tok) >= 3 and set(tok) <= RULE_CHARS


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    at_line_start = len(prefix.token_strings) == 1 or "\n" in prefix.token_strings[-2]
    if not at_line_start:
        return None, 0.0
    if tok in FENCE:
        return None, -1.5
    if is_rule(tok):
        return None, -0.7
    if tok in HTML_OPEN:
        return None, -0.5
    if tok in PAGE:
        return None, -0.8
    if tok in DATES:
        return None, -0.4
    return None, 0.0

programs.luna:
"""Mark conspicuous text-format boundaries and a few document-heading labels.

This component is usually quiet; its large negative responses in the sample
cluster around code fences and other structural punctuation. It also responds
weakly to several words commonly used to begin a section or page label.
"""
READS = ()

FENCES = {"```", "``"}
STRUCTURAL_MARKS = {
    "@@": -2.4,
    "?>": -0.8,
    "/*": -0.55,
    '"""\n': -0.35,
    "###": -0.25,
    "---": -0.3,
    "---\n\n": -0.22,
    "//----------------------------------------------------------------": -0.7,
}
SECTION_LABELS = {
    "Question", "Last", "Title", "Article", "Show", "More",
    "Explanation", "Similar", "This", "Advertisements", "View",
    "Created", "Optional", "Fields", "Code",
}


def at_line_start(prefix):
    ids = prefix.token_ids
    docs = prefix.document_ids
    if len(ids) < 2 or docs[-1] != docs[-2]:
        return True
    # Only inspect a short suffix; a newline is normally in the previous token.
    suffix = ""
    for i in range(len(ids) - 2, max(-1, len(ids) - 9), -1):
        if docs[i] != docs[-1]:
            break
        suffix = prefix.token_strings[i] + suffix
        if "\n" in prefix.token_strings[i] or "\r" in prefix.token_strings[i]:
            break
    before = suffix.rsplit("\n", 1)[-1].rsplit("\r", 1)[-1]
    return not before.strip(" \t")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in FENCES:
        return None, -1.6
    if token in STRUCTURAL_MARKS:
        return None, STRUCTURAL_MARKS[token]
    if token.strip() == "diff" and at_line_start(prefix):
        return None, -0.3
    if token.strip() in SECTION_LABELS and at_line_start(prefix):
        return None, -0.4
    return None, 0.0

programs.sol:
"""Approximate the component's structured name-boundary responses.

Middle-dot separators and Han geographic, language and name suffixes are
positive. A negative Chinese transcription-syllable cue is stronger when
syllables are consecutive. Preceding transcription text or katakana boosts
following Han text, particularly suffixes.
Smaller offsets cover kana fragments, English geography and chat markers.

These are surface cues, not proof that text is a name. The many weaker lexical
responses are not modeled. Context is one token, reset at document boundaries.
"""
READS = ()

STRONG_NAME_SYLLABLES = frozenset('斯特尔爾亚亞尼诺諾勒拉迪托萨薩')
NAME_SYLLABLES = frozenset(
    '阿埃艾奥奧巴贝貝比波布达達德蒂杜多菲弗夫福格哈赫'
    '胡霍基吉加杰傑卡凯凱科克莱萊兰蘭雷里利莉丽麗琳罗'
    '羅鲁魯路卢盧洛马馬玛瑪梅米莫姆穆纳納娜奈帕佩皮普'
    '齐齊乔喬塞莎沙什塔泰坦图圖瓦维維威沃乌烏伍西希'
    '雅耶伊尤约約泽澤兹茲佐'
) | STRONG_NAME_SYLLABLES
GEOGRAPHIC = frozenset('山河湖林谷岛島城')
LOCAL_ADMIN = frozenset('县縣区區市郡镇鎮')
LANGUAGE = frozenset('语語文')
TITLE = frozenset(('族', '王子', '帝', '皇', '王', '伯', '君'))


def han(s):
    return bool(s) and all('\u4e00' <= c <= '\u9fff' for c in s)


def katakana(s):
    return bool(s) and all('\u30a1' <= c <= '\u30fa' or c == 'ー' for c in s)


def responses(token, prev):
    """Separate punctuation, syllables, suffixes, transitions, and background."""
    s = token.strip()
    foreign = bool(prev) and all(c in NAME_SYLLABLES for c in prev)
    dot = syllable = suffix = transition = 0.0
    background = 0.002
    if s == '・':
        if token.startswith(' '):
            dot = 0.65
        elif not prev or prev[-1].isspace():
            dot = 0.56
        else:
            dot = 1.5 if katakana(prev) else 0.78
    elif s == '·':
        dot = 0.44 if token.startswith(' ') else 0.8
        if not token.startswith(' ') and han(prev):
            dot = 2.1 if foreign else 1.35
    elif s in ('･', '‧', '•'):
        dot = {'･': 0.7, '‧': 0.4, '•': 0.075}[s]
    elif han(s):
        background = 0.006
        if s in STRONG_NAME_SYLLABLES:
            syllable = -0.60 if foreign else -0.08
        elif s in NAME_SYLLABLES:
            syllable = -0.11 if foreign else -0.025
        elif s == '氏':
            suffix = 0.8
        elif s in ('省', '州'):
            suffix = 0.64
        elif s in GEOGRAPHIC:
            suffix = 0.20
        elif s in LANGUAGE:
            suffix = 0.24
        elif s in TITLE:
            suffix = 0.18
        elif s == '式':
            suffix = 0.16
        elif s in LOCAL_ADMIN:
            suffix = 0.04
        if foreign:
            transition += 0.065
            if suffix:
                transition += 0.53
        if katakana(prev):
            transition += 0.25
    elif katakana(s):
        background = -0.05
        if s.endswith('ー'):
            background += 0.15
        if s in 'ァィゥェォャュョッ':
            background -= 0.12
    elif token.startswith(' ') and s in ('County', 'Province'):
        background = 0.20
    elif token.startswith(' ') and s.lower() in ('river', 'lake', 'valley', 'forest'):
        background = 0.15
    elif s in ('<think>', '<tool_call>', '<tool_response>'):
        background = 0.12
    return dot, syllable, suffix, transition, background


# Punctuation, syllables, suffixes, context, and background, respectively.
# Calibrated using output changes on training rows.
WEIGHTS = (0.85, 1.0, 0.90, 1.15, 0.80)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    values = responses(token, prev)
    value = sum(w * v for w, v in zip(WEIGHTS, values))
    return (doc, token), float(value)

