programs.sol:
"""A local minus/hyphen-start detector with a few lexical side responses.

One-character ASCII digits after a sign are positive, especially 1 and 2.
Spacing, opening delimiters, code sentinels, diff hunks and numeric command
options change the strength. Alphabetic tokens after '-' are stronger in
recognizable command/option contexts; negative infinity and CSS vendor
prefixes are handled explicitly. Smaller responses mark test word forms,
the literal tokens 'name' and 'workspace', and vertical pipe separators.

These rules approximate the prominent training activations, not all of the
component's context-dependent background variation. Only the last 160 text
characters are carried, with a reset at every document boundary.
"""
import re

READS = ()
SIGNS = '-−–—⁻±+'
SHELL = re.compile(
    r'\b(?:grep|python\d?|pip\d?|find|rm|ls|cat|head|tail|curl|git|mvn|'
    r'bash|perl|sed|ssh|pytest|npm|make|cargo|gcc|pacman|apt-get|'
    r'cp|gunzip|ditto|chown|apk|install|java|cmake|mkdir|ln|echo|test)\b'
)
COMPARISONS = {'eq', 'ne', 'gt', 'ge', 'lt', 'le'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._/-').lower()
    value = 0.0
    if word == 'test':
        value = 0.70
    elif word in {'tests', 'tester'}:
        value = 0.48
    elif word in {'testing', 'tested'}:
        value = 0.35
    elif token in {'name', 'workspace'}:
        value = 0.56
    elif token.strip() == '|':
        value = 0.17 if '\n' in token else (0.55 if token[0] == ' ' else 0.38)

    before = tail.rstrip()
    if before and before[-1] in SIGNS:
        sign, left = before[-1], before[-2:-1]
        gap = len(tail) != len(before)
        if token in '0123456789' and len(token) == 1:
            value = 1.6 if token == '1' else 1.2 if token == '2' else 0.72
            if token == '0':
                value = 1.04
            if gap:
                value *= 0.46
            elif left.isspace() or not left:
                value += 1.25
            elif left in '([{=,+;^':
                value += 1.80
            elif left in '`\"\'':
                value += 2.7
            elif left.isalpha():
                value += 0.50
            if sign in '–—±':
                value *= 0.72
            elif sign == '+':
                value *= 0.22
            if re.search(r'(?:head|tail) +-+$|@@ -$', tail):
                value += 1.6
            elif sign == '-' and left == '`':
                value += 1.3
            elif sign == '-' and token == '1' and not gap:
                if left == '[' or re.search(r'(?:=|return) -$', tail):
                    value += 0.8
        elif not gap and sign == '-' and token.isascii() and token.isalpha():
            flag = left.isspace() or left in "`\"'-"
            shell = bool(SHELL.search(tail[-100:])) or bool(re.search(
                r'/test|/workspace|\.(?:py|sh|go|js|json)\b', tail[-100:]
            ))
            quoted = left in "`\"'" or 'add_argument' in tail
            if token in {'Inf', 'inf', 'Infinity'}:
                value = 2.8
            elif token in {'webkit', 'moz', 'ms'}:
                value = 3.8
            elif token in COMPARISONS and flag:
                value = 3.8
            elif token == 'name' and flag:
                value = 4.8
            elif len(token) == 1:
                value = 3.1 if flag and (shell or quoted) else 0.95
            elif flag and shell and len(token) <= 6:
                value = 3.0 if len(token) <= 3 and left != '-' else 1.5
            else:
                value = -0.10
        elif not gap and sign == '-' and token.startswith(' '):
            value = -0.28
    if token == '¹':
        value = 4.0 if before.endswith('⁻') else 0.25
    return (doc, (tail + token)[-160:]), float(value)

