"""Estimate sparse responses from token text and the preceding token.

Test/workspace labels and vertical bars are positive cues. Number starts are
strongest after a sign; a spaced hyphen also cues short letter tokens. Superscript
minus-one notation is a rare strong cue.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()
    stripped = token.strip()

    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]

    if stripped == "¹" and previous.strip() == "⁻":
        return None, 4.0
    if stripped.isascii() and stripped.isdigit():
        if previous == " -":
            return None, 2.45
        if previous.strip() in {"-", "−", "–", "—"}:
            return None, 1.25
        if previous.strip() == "+":
            return None, 0.41
    if previous == " -" and stripped.isascii() and stripped.isalpha():
        return None, 1.28 if len(stripped) == 1 else 0.58
    if previous.strip() in {"-", "−", "–", "—"} and stripped.isascii():
        if stripped.isalpha() and len(stripped) == 1:
            return None, -0.15
    if "test" in lower:
        return None, 0.66
    if "workspace" in lower:
        return None, 0.68
    if "|" in token:
        return None, 0.58
    if stripped.lower() == "name":
        return None, 0.43
    if stripped.isascii() and stripped.isdigit():
        if previous.strip().isascii() and previous.strip().isdigit():
            return None, 0.001
        return None, 0.092
    return None, 0.009

programs.sol:
"""A lexical metadata signal, not a general detector of importance.

Chat/tool boundaries, underscore separators, and value/file/argument labels
receive positive scores. Long underline rules and braced math subscripts do
not receive the separator score. Word spelling and the immediately preceding
token refine the estimate. Boundary scores increase with document position.
Everything else is zero; state resets at each document boundary.
"""
import re

READS = ()
MARKERS = {
    '<tool_call>': 1.31, '</tool_call>': 1.15,
    '<tool_response>': 1.12, '</tool_response>': 0.15,
    '<think>': 0.21, '<|im_start|>': -0.05,
}
GREEK = {'alpha', 'beta', 'gamma', 'delta', 'lambda', 'sigma',
         'tau', 'phi', 'psi', 'theta', 'omega'}


def lexical(token, previous):
    s, prev = token.strip(), previous.strip()
    if s in MARKERS:
        return MARKERS[s]
    if '_' in s and not re.search(r'\w', s.replace('_', '')):
        if s.endswith(('{', '\\')):
            return 0.0
        if s.count('_') > 2:
            return 0.13
        if '\n' in token or not s.endswith('_'):
            return 0.35
        if s.count('_') == 2:
            return 0.62 if previous.endswith('_') else 1.30
        if prev == 'NAME':
            return 0.77
        if (len(prev) == 1 and prev.isalpha()) or prev in GREEK:
            return 0.28
        return 0.60 if token[:1].isspace() else 0.54
    word = s.strip('._-/()[]<>\"\'=:,')
    low = word.lower()
    if low in {'value', 'values'} or s in {'值', '값'}:
        if prev.lower() == 'absolute':
            return 0.35
        if word.isupper():
            return 0.60 if low == 'values' else 0.88
        score = 1.14 if word[:1].isupper() else 0.96
        return score - (0.15 if s != word else 0.0)
    if re.fullmatch(r'[A-Za-z]+Values?', word):
        return 0.65
    if low in {'file', 'files'} or s in {'文件', 'ファイル'}:
        return 0.72 if not token[:1].isspace() and word.islower() else 0.92
    if low in {'param', 'params', 'parameter', 'parameters'} or s == '参数':
        if prev.lower() in {'required', 'optional'}:
            return 0.84
        if low in {'param', 'params'}:
            return 0.40 if token[:1].isspace() else 0.62
        return 0.25 if low == 'parameters' else 0.37
    if low in {'arg', 'args', 'argument', 'arguments', 'kwargs'}:
        if low in {'args', 'kwargs'}:
            return 0.60
        return 0.55 if low == 'arguments' else 0.29
    if low in {'name', 'names'}:
        if prev.lower() in {'param', 'parameter'}:
            return 0.92
        if prev.lower() == 'given':
            return 0.47
        return 0.45 if token == 'name' else 0.24
    return 0.17 if low in {'path', 'paths'} else 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    if token == '<|im_end|>':
        value = 2.54 - 1.35 / (position + 1) ** 0.6
    elif token == '</think>':
        value = 0.95 - 0.28 / (1 + position / 10)
    else:
        value = lexical(token, previous)
    return (doc, position, token), float(value)

programs.haiku:
"""Candidate 3: chat/tool markers, underscore placeholders, and generic
programming words (value, file, parameter, argument, name)."""
READS = ()

MARKERS = {"<|im_end|>": 2.4, "<tool_call>": 1.3, "</tool_call>": 1.15,
           "<tool_response>": 1.1, "</tool_response>": 0.15, "</think>": 0.9, "<think>": 0.2}
WORDS = {"value": 1.0, "values": 0.95, "值": 1.1, "valor": 0.5, "valeur": 0.35,
         "file": 0.8, "files": 0.9, "文件": 0.9, "path": 0.2,
         "param": 0.6, "params": 0.55, "parameter": 0.6, "parameters": 0.25, "参数": 0.4,
         "arg": 0.3, "args": 0.7, "kwargs": 0.7, "argument": 0.35, "arguments": 0.5,
         "name": 0.4, "names": 0.3}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s in MARKERS:
        return carry, MARKERS[s]
    bare = s.strip(" ./<>()[]{}\"'`&*$@")
    if bare == "_" or bare == "__":
        return carry, 1.2 if bare == "__" else 0.6
    if "__" in s and len(s.strip()) <= 3:
        return carry, 0.5
    if "_" in s and not bare.strip("_"):
        return carry, 0.1
    return carry, WORDS.get(bare.strip("_-").lower(), 0.0)

programs.luna:
"""Recognize message-boundary and code/schema markers in the current token.

This is a sparse, text-based approximation: most tokens contribute almost
nothing, while chat control tokens and field/name-like spellings get a positive
activation.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    # Conversation and tool-control markers have the clearest, largest effects.
    controls = {
        "<|im_end|>": 2.45,
        "<tool_call>": 1.28,
        "</tool_call>": 1.16,
        "<tool_response>": 1.13,
        "</think>": 0.80,
    }
    if token in controls:
        return None, controls[token]

    # Repeated underscores are characteristic of identifiers and placeholders.
    if "__" in token:
        return None, 1.30
    if "_" in token:
        return None, 0.70

    # Field-oriented code and documentation vocabulary.
    word = token.strip().strip(".,:;!?(){}[]\"'`<>/").lower()
    if word in {"value", "values", "fieldvalue"}:
        return None, 0.95
    if word in {"param", "parameter", "parameters"}:
        return None, 0.70
    if word in {"file", "files"}:
        return None, 0.90
    if word in {"name", "names", "argument", "arguments", "path"}:
        return None, 0.50
    if word in {"string", "strings"}:
        return None, 0.40

    return None, 0.0

programs.sol:
"""Approximate an English possessive-s signal.
Most apostrophe-s tokens are strongly positive, except after common contraction
bases. Human plurals, indefinite possessors and question words are weaker.
Spelling, capitalization, split tokenization and document starts adjust strength.
A bare letter s gets a small response; other weak lexical effects are ignored.
Only the current word and previous token are remembered, reset per document.
"""
READS = ()
APOSTROPHES = "'’‘"
CONTRACTION_BASES = frozenset((
    'it', 'he', 'she', 'that', 'there', 'here', 'let',
))
QUESTION_WORDS = frozenset(('what', 'who', 'where', 'when', 'how', 'why'))
HUMAN_PLURALS = frozenset(('men', 'women', 'people'))
INDEFINITE_POSSESSORS = frozenset((
    'one', 'someone', 'anyone', 'everyone', 'noone',
    'somebody', 'anybody', 'everybody', 'nobody', 'else',
))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    word, previous = ('', '') if fresh else carry[1:]
    token = prefix.token_strings[-1]
    base = word.lower()
    suffix = len(token) == 2 and token[0] in APOSTROPHES and token[1] in 'sS'
    split_suffix = token == 's' and previous.endswith(tuple(APOSTROPHES))
    value = 0.0
    if suffix or split_suffix:
        if base in CONTRACTION_BASES:
            value = -0.04 if base == 'it' else -0.10
        elif base in QUESTION_WORDS:
            value = 0.18
        elif base == 'children':
            value = 0.64
        elif base in HUMAN_PLURALS:
            value = 0.49
        elif base in INDEFINITE_POSSESSORS or base == 'today':
            value = 0.80
        elif suffix:
            value = 1.09 if token[0] == '’' else 1.06
            if token[1] == 'S':
                value = 0.90
            elif token[0] == '‘':
                value = 0.70
            if fresh:
                value = 0.78
        else:
            value = 0.12 if previous[:1].isspace() else 0.50
        word = ''
    else:
        if token == 's':
            value = 0.06
        # Preserve a word across an apostrophe so split suffixes see its base.
        for ch in token:
            if ch.isalpha():
                word = word + ch
            elif ch not in APOSTROPHES + '\\':
                word = ''
        word = word[-40:]
    return (doc, word, token), float(value)

programs.luna:
"""Use apostrophe-s as a rare positive cue, with a small contraction exception.

The rule is orthographic and local: it does not parse syntax. It recognizes
suffixes inside one token and suffixes split across an apostrophe and s.
"""

READS = ()

APOSTROPHES = ("'", "’", "‘")
SUFFIXES = tuple(mark + "s" for mark in APOSTROPHES)
CONTRACTION_BASES = {
    "i", "you", "he", "she", "it", "we", "they", "who", "what",
    "that", "there", "here", "where", "when", "how", "why", "let",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = None
    if carry is not None and carry[1] == doc:
        previous = carry[0]

    lower = token.lower()
    base = previous.strip().lower() if previous is not None else ""
    if any(lower.endswith(suffix) for suffix in SUFFIXES):
        value = 0.0019 if base in CONTRACTION_BASES else 1.05
    elif lower == "s" and previous is not None and previous.endswith(APOSTROPHES):
        value = 0.70
    else:
        value = 0.0019

    return (token, doc), float(value)

programs.sol:
"""Approximate a lexical 'open' versus '-ing' word-family signal.

'Open', related spellings, and selected Chinese opening words are positive;
the listed activity-noun forms are negative, even when used as verbs.
Selected Chinese setting/building/reading words have smaller negatives.
Split -ing endings use the unfinished word in carry. Chat role/closing
markers have separate small responses. Everything else stays near zero.
This recognizes word forms, not grammatical noun/verb distinctions.
"""
import re

READS = ()

# Activity-derived word forms, regardless of their grammatical use.
ING_WORDS = {
    'building': -0.78,
    'setting': -0.89,
    'reading': -0.75,
    'meeting': -0.65,
    'meaning': -0.58,
    'bearing': -0.58,
    'binding': -0.36,
    'finding': -0.30,
    'feeling': -0.39,
    'drawing': -0.41,
    'hearing': -0.41,
    'painting': -0.39,
    'clearing': -0.44,
    'cleaning': -0.28,
    'embedding': -0.33,
    'gathering': -0.37,
    'dwelling': -0.35,
    'rendering': -0.28,
    'proceeding': -0.30,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    match = re.search(r'[A-Za-z]+$', previous + token)
    whole_word = match[0][-40:] if match else ''
    state = (doc, whole_word, position)
    word = token.strip().lstrip('._/(-').lower()
    value = -0.002
    if token == 'assistant':
        value = 0.44 if position == 1 else 0.61
    elif token == '<|im_start|>':
        value = -0.036 if position else -0.001
    elif token == '<|im_end|>':
        value = -0.039
    elif token == '</tool_response>':
        value = 0.103
    elif token == '</tool_call>':
        value = 0.074
    elif word == 'open':
        value = 1.40 if token.strip()[:1].isupper() else 1.30
        if token.startswith('.'):
            value = 1.0 if token[1:2].isupper() else 1.75
        elif token.startswith(('-', '(')):
            value = 1.14
    elif word in ('opened', 'opens', 'openness'):
        value = 0.62 if word == 'opened' else 0.75
    elif word == 'openly':
        value = 0.80
    elif word == 'opening':
        value = 0.10
    elif word in ('isopen', 'reopen', 'fopen'):
        value = 0.9 if word == 'isopen' else 1.05 if word == 'fopen' else 0.60
    elif word in ('开', '開', '开放', '打开', '公开', '公開'):
        value = 0.44 if word == '開' else 0.55
    elif word in ('设置', '建筑', '阅读'):
        value = -0.28
    elif word in ING_WORDS:
        value = ING_WORDS[word]
    elif word.endswith('ings') and word[:-1] in ING_WORDS:
        value = ING_WORDS[word[:-1]] * 0.60
        if word == 'settings':
            value = -0.35 if token.startswith(('.', '/')) else -0.64
        elif word == 'meanings':
            value = -0.58
    elif token.lower() in ('ing', 'ings', 'ting', 'tings', 'etting'):
        # The same nominal ending can be split away from its word stem.
        singular = whole_word.lower().removesuffix('s')
        if singular in ING_WORDS:
            value = -0.90
        elif token.lower() == 'etting':
            value = -0.60
        elif whole_word.lower().endswith('tting'):
            value = -0.40
        elif token.lower().endswith('s'):
            value = -0.20
        elif token.isupper():
            value = -0.16
        elif token.lower() == 'ting':
            value = -0.12
        else:
            value = -0.05
    return state, value

programs.haiku:
"""Layer-0 MLP down-projection component 1771: a word detector.

What it does, in plain terms: it reads the current token and writes a signed
value into the residual stream that depends almost only on which word the token is.

* Positive on the word "open" (any case, also as a code/path fragment such as
  "/open" or ".open"): about +1.3. The inflections "opened", "opens", "reopen"
  are about +0.7, and the Chinese/Japanese words for "open" (开, 開, 打开, 公开,
  ...) about +0.5.
* Positive on the chat-role token "assistant" (the word after
  "<|im_start|>"): about +0.6.
* Negative on a small set of "-ing" nouns, strongest for building, setting,
  reading, meeting, meaning (and their plurals and capitalised forms): about -0.7.
  A second, weaker group (binding, drawing, feeling, finding, painting,
  hearing, cleaning, clearing, bearing, wiring, ...) is about -0.35.
* A bare "ing"/"ings" suffix token is slightly negative (-0.15).
* Everything else is 0.

The value depends only on the current token, not on context. The word lists
are the concepts; the rest of the vocabulary is treated as zero.
"""

READS = ()

# Words are compared after dropping leading punctuation and lowercasing,
# so "Open", " open", "/open" and ".open" all count as "open".
OPEN_FORMS = {"open": 1.3, "opened": 0.7, "opens": 0.7, "reopen": 0.7}
CJK_OPEN = {"开", "開", "开放", "開放", "打开", "公开", "公開", "开了"}
ROLE_WORDS = {"assistant": 0.6}
NEG_STRONG = {
    "building", "buildings", "setting", "settings", "reading", "readings",
    "meeting", "meetings", "meaning", "meanings",
}
NEG_WEAK = {
    "binding", "bearing", "wiring", "fitting", "drawing", "painting", "hearing",
    "feeling", "finding", "cleaning", "clearing", "mapping", "rendering",
    "coating", "embedding", "gathering", "proceeding", "beginning",
}
SUFFIX_TOKENS = {"ing", "ings"}


def _word(token):
    return token.strip().lstrip("./_-=(\"'").lower()


def _value(token):
    word = _word(token)
    if word in OPEN_FORMS:
        return OPEN_FORMS[word]
    if token.strip() in CJK_OPEN:
        return 0.5
    if word in ROLE_WORDS:
        return ROLE_WORDS[word]
    if word in NEG_STRONG:
        return -0.7
    if word in NEG_WEAK:
        return -0.35
    if word in SUFFIX_TOKENS:
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    # Stateless: the activation at this position depends only on the current token.
    return None, _value(prefix.token_strings[-1])

programs.luna:
"""Recognize an assistant-role token, open-word forms, and a few -ing nouns."""

READS = ()
ING_NOUNS = frozenset({
    "building", "carving", "drawing", "embedding", "feeling",
    "finding", "meaning", "meeting", "meetings", "reading",
    "setting", "settings",
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower().strip(".,:;!?\"'()[]{}")

    if token == "assistant":
        return None, 0.61

    if word in ("open", "_open"):
        return None, 1.35
    if word == "opened":
        return None, 0.53
    if word in ING_NOUNS:
        return None, -0.60
    return None, 0.0

programs.sol:
"""A short-range spelling signal around the letter C.

Short C-initial pieces at a document's start, or continuing a piece
ending in C, receive the largest predictions. Other alphabetic continuations
of a short C-ending piece receive a smaller positive prediction. Spaces and
punctuation usually stop this signal. Standalone capital C is also positive.
There are weaker analogues for Cyrillic к, ц and сч, and Greek κ.
The word 'cancer' also receives a positive prediction.
The magnitudes summarize training observations, not exact token identities.
Only the previous token is remembered, and documents reset that memory.
"""
READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    lower = token.lower()
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    reset = carry is None or carry[0] != doc
    carry = (doc, lower)
    length = len(token)
    first_c = lower.find('c')
    alpha = token[:1].isalpha()
    value = 0.0

    if reset and first_c >= 0 and first_c <= 2:
        trailing = length - first_c
        if trailing == 1:
            value = (2.05, 1.33, 0.46)[first_c]
        elif trailing == 2:
            value = 0.75 if first_c == 0 else 0.06
        elif trailing == 3:
            value = 0.44 if first_c == 0 else 0.10
        elif trailing == 4:
            value = 0.14
    elif reset and token in 'кКсСчЧ' and len(token) == 1:
        value = 1.30 if lower == 'к' else 0.60
    elif lower.strip() == 'cancer':
        value = 0.56
    elif previous.endswith('c'):
        short_previous = len(previous.strip()) <= 4
        if alpha:
            if first_c == 0:
                if not short_previous:
                    value = 0.12
                elif length <= 3:
                    value = 2.05
                elif length == 4:
                    value = 1.05
                else:
                    value = 0.42
            elif length <= 3:
                if not short_previous:
                    value = 0.07
                elif lower[0] in 'aouy':
                    value = 0.54
                elif lower[0] in 'ei':
                    value = 0.31
                else:
                    value = 0.27
            elif first_c >= 0 and first_c <= 3:
                value = 0.44 if short_previous else 0.07
            else:
                if not short_previous:
                    value = 0.01
                else:
                    value = 0.25 if lower[0] in 'aouy' else 0.08
        elif first_c >= 0 and first_c <= 1:
            value = 0.53 if len(previous.strip()) <= 2 else 0.15
    elif (first_c == 1 and 'c' in previous[:2]
          and len(previous.strip()) <= 5):
        value = 0.50 if length <= 3 else (0.16 if length <= 6 else 0.03)
    elif first_c == 0:
        near_c = previous.rfind('c') >= max(0, len(previous) - 4)
        if near_c:
            value = 0.45 if length <= 3 else 0.09
        elif length in (2, 3):
            value = 0.23 if token.isupper() else 0.10
        elif length >= 4:
            value = -0.02
    elif previous.endswith('ц') and alpha:
        value = 0.25
    elif previous.endswith('к') and alpha:
        value = 0.20 if len(previous.strip()) == 1 else 0.06
    elif previous.endswith('с') and lower.startswith('ч'):
        value = 0.40
    elif previous.endswith('κ') and alpha:
        value = 0.20

    if value == 0.0 and not reset:
        letters = ''.join(ch for ch in token if ch.isalpha())
        if letters == 'C':
            value = 0.11

    return carry, float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 1772: a "capital C word-piece" detector.

What it does, in plain terms: the component is almost always silent. It wakes up on a
letters-only word piece (no leading space) that comes right after a standalone capital C
(or lowercase c) fragment, as in a word or acronym being spelled out. It is strongest on
that piece, for example the "orporation" in "Wyoming C|orporation", the "ancer" in
"anti-c|ancer", or the "GL" in "SSC|GL". It is weakly positive on the C or c fragments
themselves and on word pieces that start with c.

Rules, per token (a new document resets the context):
  - a letters-only piece with no leading space, right after a C fragment ("C", "c",
    "-C", "_C", "AC", "IC", "EC"): 0.4;
  - a standalone "C" or "c" token: 0.08;
  - a letters-only piece starting with c or C: 0.04;
  - everything else, including ordinary space-led words: 0.

The values are group means from 1024 training rows. The rules explain only about 5% of the
variance on held-out rows: most of the component's large activations occur in contexts
that no short rule captures.
"""

READS = ()

C_FRAGMENTS = {"C", "c", "-C", "_C", "AC", "IC", "EC"}


def _is_piece(s):
    return s.isalpha() and s.isascii() and not s.startswith(" ")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    t = prefix.position
    same_doc = t > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]
    prev = prefix.token_strings[-2] if same_doc else ""
    if prev.strip() in C_FRAGMENTS and _is_piece(cur):
        value = 0.4
    elif cur.strip() in ("C", "c"):
        value = 0.08
    elif _is_piece(cur) and cur[0] in "cC":
        value = 0.04
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a token-spelling feature, not a semantic topic.

Initial V followed by consonants, especially short acronyms, is strongly
positive. Short W clusters and related Cyrillic/Arabic spellings are weaker
positive cues. Terminal V in longer fragments tends to be negative. There
are small related F/U rules and fixed offsets for conversation delimiters.
The program is stateless; it leaves most ordinary tokens at zero and does
not explain their smaller, word-specific differences.
"""
READS = ()
VOWELS = frozenset('aeiouy')
CYRILLIC_VOWELS = frozenset('аеёиоуыэюяьъ')


def token_value(token):
    s = token.strip().lstrip('._/-')
    low = s.lower()
    n = len(s)
    if not n:
        return 0.0
    if token == '<tool_response>':
        return -0.15
    if token == '<|im_start|>':
        return 0.037
    if token in ('<|im_end|>', '<|endoftext|>'):
        return -0.025

    # V onsets, including the comparison word represented by "vs".
    if low == 'versus':
        return 0.46
    if low[0] == 'v':
        if n == 1:
            return 0.06 if s.islower() else 0.0
        if low[1] in 'bcdfghjklmnpqrstxz':
            if n == 2:
                return 0.72 + 0.16 * s.isupper()
            return 0.7 if not any(c in VOWELS for c in low) else 0.4
        if low[1] in 'vy':
            return 0.3 if n <= 3 else 0.04
        return 0.04 + 0.07 * s.isupper()

    # Unusual short W/F combinations, rather than ordinary WH/WR words.
    if n == 2 and low[0] == 'w':
        if low[1] in 'bcdfgjklmnpqstvxz':
            return 0.47 + 0.12 * s.isupper()
        if low[1] in 'hr':
            return 0.14
    if n <= 3 and low.startswith(('uv', 'uw')):
        return 0.32
    if n == 2 and low[0] == 'f' and low[1] in 'bgh':
        return 0.28

    # Cyrillic ve and Arabic waw are analogous V/W onsets.
    if low.startswith('в'):
        if n == 1:
            return 0.08 if not token[0].isspace() else 0.02
        if n == 2 and low[1] not in CYRILLIC_VOWELS:
            return 0.17 if low[1] == 'з' else 0.5
        return 0.14 if n <= 3 else 0.09
    if low.startswith('و') and 2 <= n <= 3:
        if low[1] not in 'ايأإآیى':
            if n == 2 and low[1] in 'زص':
                return 0.75
            return 0.26 if n == 2 else 0.17
    if n == 2 and low[0] == 'у':
        return 0.12

