import re

READS = ()

# Nominal references to tasks and discrete acts; strengths shared by families.
FAMILIES = (
    (1.2, 'query queries instruction instructions transformation transformations '
          'manipulation changes edits adjustments'),
    (0.8, 'transaction transactions modification modifications invocation '
          'invocations maneuver maneuvers surgery swaps operative'),
    (0.6, 'action actions request requests task procedure procedures calculations '
          'computations mutation mutations edge edges gate gates cmd sql'),
    (0.35, 'change call edit edited modify modified changed transform tested '
           'testing operating operator operators operational requested job jobs '
           'perform move moves direction directions update updates'),
    (0.65, 'calls ops oper'),
    (0.3, 'op comm'),
    (0.9, 'tasks'),
    (0.54, 'performed'),
)
STRENGTH = {w: a for a, words in FAMILIES for w in words.split()}
FOREIGN = {
    '操作': 2.8, '的操作': 2.3, '命令': 1.8, '一步': 1.8, '작업': 1.8,
    '步骤': 1.1, '请求': 1.1, '修改': 1.1, '更改': 1.1, '指令': 1.1,
    '令': 1.1, '查询': 0.8,
    '步': 0.8, '歩': 0.8, '任务': 0.8, 'опер': 0.8, 'команд': 0.8,
}
COMPUTING = set('''arithmetic mathematical matrix row memory read write insert
delete mutation query file database network string list array convolution
stencil git code programming python function method api bash shell'''.split())
ORGANIZATIONAL = {'military', 'business', 'corporate', 'company', 'navy', 'war'}
EDIT_NOUNS = {'change', 'changes', 'edit', 'edits', 'modification', 'modifications'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, last_value = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    raw = token.strip().lstrip('._/-(\\')
    word = raw.lower()
    value = STRENGTH.get(word, FOREIGN.get(raw, 0.0))
    if token == '<|endoftext|>':
        value = 1.83
    elif word in {'operation', 'operations'}:
        value = 2.1 if not raw[:1].isupper() else 1.5
    elif word in {'command', 'commands'}:
        value = (2.15 if word == 'commands'
                 else (1.65 if token[:1].isspace() else 1.28))
    elif word in {'test', 'tests'}:
        value = (0.35 if token.startswith('/')
                 else (0.61 if token.startswith('_') else 0.8))
    elif word in {'step', 'steps'}:
        value = (1.24 if word == 'steps'
                 else (0.61 if raw[:1].isupper() else 0.82))
    elif word in {'ation', 'ations', 'ion', 'ions', 'tion', 'tions'}:
        value = 0.33 if raw.isupper() else 0.15
    if word in {'operation', 'operations', 'change', 'changes', 'made', 'to', 'on'}:
        words = re.findall('[a-z]+', history.lower())
        recent, near = set(words[-12:]), set(words[-3:])
        previous = words[-1] if words else ''
        if word in {'operation', 'operations'}:
            value += 0.8 * bool(recent & COMPUTING)
            value -= 0.8 * bool(recent & ORGANIZATIONAL)
        elif word in {'change', 'changes'}:
            value += 0.7 * bool(near & {'make', 'making', 'made', 'minimal', 'any'})
        elif word == 'made' and near & EDIT_NOUNS:
            value = 1.85
        elif word == 'on' and previous in {'operation', 'operations'}:
            value = 1.1
        elif word == 'to':
            if previous in EDIT_NOUNS:
                value = 0.65 if previous == 'change' else 1.4
            elif previous in {'call', 'calls'}:
                value = 1.04
            elif previous in {'request', 'requests', 'query', 'commands'}:
                value = 0.6
            elif previous == 'made' and last_value > 0.8:
                value = 1.65
    return (doc, (history + token)[-160:], value), float(value)

