    "behavioral", "lifestyle", "trend", "trends", "trending", "technique",
    "techniques", "convention", "conventions", "customs", "tactic", "tactics",
    "routine", "routines", "ritual", "rituals", "tendency", "tendencies",
    "propensity", "mindset", "attitude", "attitudes", "行为", "理念", "趋势",
    "技巧", "方式", "做法", "风格", "生活", "暮らし",
