    "characteristics", "trait", "traits", "fashion", "heritage", "customary",
    "ceremony", "etiquette", "vogue", "methodology", "methodologies", "paradigm",
    "conventional", "custom", "culture", "制度", "手法", "特性", "性格", "精神",
    "风", "风味",
}
# Looser words: process, way, design, nature, life, strategy, skill.
TIER_D = {
