    'оз': -0.57, 'из': -0.27, 'ез': -0.28, 'уз': -0.53,
    'za': -0.4, 'zi': -0.4, 'zer': -0.4, 'zz': -0.5, 'ž': -0.5,
    'از': -2.4,
