    word = token.strip()
    s = word.lower()
    boundary = token[:1].isspace()
    if s == 'communication':
        return 1.3 if boundary else 0.8
    if s.startswith('communicat'):
        return 0.45 if s == 'communications' else 0.85
    if s in ('通信', '沟通', 'skill', '技能'):
        return 0.8
    if s in COMPETENCE:
