        a, b = len(before), max(0, len(after) - 1)
        if not after:
            return -3.2 / (1 + 0.18 * max(0, a - 1))
        if after[0] in 'ey':
            strength = 3.85 + 0.5 * before.endswith('r')
            strength -= 1.4 * (a == 1 and before != 'r')
