        if s == 'раз':
            return -3.45 if boundary else -4.3
        if s.endswith('аз') and len(s) == 3:
            return -1.7
        if s.endswith('раз'):
            return -1.1 if boundary else -1.65
        return -0.7 / (1 + 0.5 * max(0, len(s) - 3))
