"""Detect written ones, especially the leading digit of a number.

An ASCII 1 starting a number has a strong negative activation. Continuing a
digit run largely removes that response; repeating 1 can reverse its sign.
A decimal point or comma weakens the response; an identifier underscore
strengthens it. Subscript, superscript and fullwidth ones are also negative.
A 2 inside a digit run is mildly positive. Ordinary text stays near zero.
State is reset at document boundaries.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, run, decimal_digit = '', 0, ''
    else:
        _, previous, run, decimal_digit = carry

    value = -0.0016
    if s == '1':
        if not previous:
            value = -1.53
        elif run:
            if previous == '1':
                value = 0.19 if run == 1 else 0.33
            else:
                value = -0.11 if run == 1 else -0.015
        elif previous == '.':
            value = -0.83
            if decimal_digit:
                value = -0.33 if decimal_digit == '1' else -0.46
        elif previous.endswith(','):
            value = -0.76
        elif previous.endswith('_'):
            value = -1.24
        elif previous.isspace():
            value = -0.98
        else:
            value = -1.05
    elif s == '₁':
        value = -0.98
    elif s in ('¹', '１'):
        value = -0.66
    elif s == '2' and run:
        value = 0.14

    decimal_digit = previous if s == '.' and run else ''
    run = run + 1 if len(s) == 1 and s in '0123456789' else 0
    return (doc, s, run, decimal_digit), float(value)

