    elif word in COMPOUND_SHI:
        value = 2.3
    elif word in USE:
        value = 0.6
    elif word in MAKE:
        value = 1.0
    elif word in RESULT:
        value = 0.8
    elif word in PURPOSE:
        value = 0.75
    else:
        value = 0.0
    return carry, value

