programs.sol:
"""A contrast among continuations of 2: 20 is positive, 23--29 negative.

Emit a pulse on the second digit, even inside a longer number. Reduce its
magnitude inside digit strings or punctuated numbers, and later in a document.
Also handle fullwidth digits (with weaker pulses), English twenty-unit
compounds, and the ordinal suffix in 2nd. Other tokens predict zero: their
smaller lexical responses are not modeled. Reset at document boundaries.
"""

import math

READS = ()
NUMBER_SEPARATORS = frozenset('.,-/:_–−')

# Responses indexed by the next digit's numerical value.
AFTER_TWO = (1.71, -0.29, -0.01, -0.90, -1.75,
             -1.90, -1.86, -1.97, -2.03, -2.00)
UNITS = ('zero', 'one', 'two', 'three', 'four',
         'five', 'six', 'seven', 'eight', 'nine')


def digit(text):
    if len(text) == 1:
        if '0' <= text <= '9':
            return ord(text) - ord('0')
        if '０' <= text <= '９':
            return ord(text) - ord('０')
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before, position = '', '', 0
    else:
        _, previous, before, position = carry
        position += 1

    scale = 1.16 - 0.030 * math.log1p(position)
    if digit(before) is not None:
        scale -= 0.09
    elif before in NUMBER_SEPARATORS:
        scale -= 0.075
    value = 0.0
    current_digit = digit(token)
    if digit(previous) == 2:
        if current_digit is not None:
            value = AFTER_TWO[current_digit] * scale
            if previous == '２' or '０' <= token <= '９':
                value *= 0.75
        elif token == 'nd':
            value = 1.62 * scale
    else:
        # A hyphen may be its own token or attached to the unit word.
        tens = before if previous == '-' else previous
        unit = token.strip().lstrip('-').lower()
        if tens.strip().lower() == 'twenty' and unit in UNITS:
            number = UNITS.index(unit)
            value = AFTER_TWO[number] * scale
            if number in (1, 2):
                value = -0.4

    return (doc, token, previous, position), float(value)

programs.luna:
"""Track a decimal digit immediately after a standalone 2: zero is positive,
other digits negative. The harvested strong responses had this local pattern."""
READS = ()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    if prefix.token_strings[-2] != "2":
        return None, 0.0
    token = prefix.token_strings[-1]
    if token == "0":
        return None, 1.7
    if len(token) == 1 and token in "123456789":
        return None, -1.7
    return None, 0.0

programs.sol:
"""A partial surface-form approximation, not a semantic feature detector.

When a token decodes alone as the replacement character, inspect the character
completed in the full decoded text. Split katakana is usually negative: the
M row (マミムメモ) is strongest, ordered by its vowel. A preceding ー mark
usually strengthens the negative response. A few kana have positive responses.
Small tables calibrate selected Japanese forms, historical long s and symbols
by identity, without assigning meanings to their activation values.

Literal software-metadata spellings, a Thai tone-mark/N spelling, conversation
markers and carriage returns have separate rules. Other Unicode fragments
use coarse script-specific baselines. Ordinary text gets a near-zero baseline,
slightly negative at document starts. Most contextual and ordinary-word
variation remains unmodeled.
"""
import unicodedata

READS = ()

# Selected simplified Japanese forms: gathering, responding, returning, removing,
# cherry blossom, dragon, age, a base/ground, and searching.
# These are calibrations by character identity.
JAPANESE_FORMS = {
    '収': 1.4,
    '応': 0.6,
    '戻': 1.1,
    '抜': 1.5,
    '桜': 0.85,
    '竜': 1.6,
    '齢': 0.5,
    '拠': -1.4,
    '捜': 1.0,
}

# These symbols are recognized only when split between UTF-8 tokens.
SYMBOLS = {
    'ſ': 0.6,       # Historical long s.
    '∛': 1.5,      # Cube root.
    '≔': 1.1,      # Defined to equal.
    'ℚ': 0.6,      # Rational numbers.
    'ℜ': 1.6,      # Real part / black-letter R.
    'ℎ': 1.25,     # Planck constant.
    '⅓': 1.5,
    '⅔': 3.0,
    '⅜': 3.2,
    '⁻': 1.15,     # Superscript minus.
    '⁕': 1.2,      # Flower-shaped punctuation.
    '⁗': 1.3,      # Quadruple prime.
}


def step(carry, prefix, upstream):
    value = -0.002
    token = prefix.token_strings[-1]
    new_document = (prefix.position == 0 or
                    prefix.document_ids[-1] != prefix.document_ids[-2])
    if new_document:
        value = -0.015
    previous = '' if new_document else prefix.token_strings[-2]
    # Three literal software-metadata spellings, not general topic detectors.
    if token == 'github' and previous.endswith('://'):
        return None, -0.15
    if token == '/vnd' and previous.strip() == 'application':
        return None, -0.59
    if token == '_modules' and previous.strip() in ('node', '/node'):
        return None, 0.19 if previous == '/node' else 0.14
    if token == '\r':
        return None, -0.12
    if token == '้น':  # Thai mai-tho tone mark followed by the N consonant.
        return None, -0.5
    if token == '<|im_start|>':
        return None, -0.31 if new_document else 0.015
    if token == '<|endoftext|>':
        return None, -0.032
    if token == '</think>':
        return None, 0.16
    if token == '</tool_call>':
        return None, -0.125
    if token == '<|im_end|>':
        value = -0.04 if previous.startswith('</tool_') else 0.067
        return None, -0.15 if new_document else value
    if token != '\ufffd':
        return None, value
    if new_document:
        return None, -0.1
    text = prefix.text_prefixes[-1]
    ch = text[-1:]
    name = unicodedata.name(ch, '') if ch else ''
    if name.startswith('KATAKANA LETTER '):
        syllable = name.removeprefix('KATAKANA LETTER ')
        long_vowel = text[-2:-1] == 'ー'
        if syllable in ('MA', 'MI', 'MU', 'ME', 'MO'):
            vowel = 'AIUEO'.index(syllable[-1])
            value = -2.90 + 0.31 * vowel - 0.47 * long_vowel
        elif syllable in ('A', 'I', 'E'):
            value = -0.8 - 0.2 * long_vowel
        elif syllable in ('YA', 'YO'):
            value = -1.4
        elif syllable == 'TI':
            value = -0.8 - 0.3 * long_vowel
        elif syllable == 'BO':
            value = 1.9 - 0.2 * long_vowel
        elif syllable == 'HO':
            value = 1.05 - 0.5 * long_vowel
        elif syllable in ('NO', 'PI'):
            value = 1.0
        elif syllable in ('KA', 'KE', 'SE', 'DA'):
            value = -0.55 - 0.15 * long_vowel
        elif syllable == 'RI':
            value = -0.3 - 0.3 * long_vowel
        elif syllable in ('SO', 'BE', 'PE', 'PO'):
            value = 0.2 - 0.2 * long_vowel
        elif syllable == 'PA':
            value = -0.45 - 0.25 * long_vowel
        else:
            value = -0.1 - 0.2 * long_vowel
    elif ch in JAPANESE_FORMS:
        value = JAPANESE_FORMS[ch]
    elif ch in SYMBOLS:
        value = SYMBOLS[ch]
    elif ch == '\ufffd':
        value = 0.05
    elif name.startswith('ARABIC '):
        value = 0.4
    elif name.startswith(('CYRILLIC ', 'LATIN ')):
        value = 0.1
    elif name.startswith('CJK '):
        value = 0.05
    elif name.startswith('HIRAGANA '):
        value = -0.1
    return None, float(value)

"""Approximate the component's dominant response to the spelling ac.

Short pieces ending in ac receive large positive values. A leading space or
Ac title case softens bare ac; longer prefixes and continuations usually
weaken it. The continuations act, ach and ack barely fire. The spelling frac
(the TeX fraction command) is excluded. Mc, short uc/yc pieces, BC/DC, and
the Cyrillic pieces ак and аци receive smaller positive values.
Only the current token is read: context and other lexical quirks are omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip().lstrip('._/(-')
    word = token.lower()
    value = 0.0
    if 'ac' in word and word != 'frac':
        left, right = word.split('ac', 1)
        if not right:
            if not left:
                value = 3.1 if token == 'Ac' else (
                    3.45 if raw[:1].isspace() else 4.9)
            elif len(left) == 1 and left in 'fjdhz':
                value = 2.9
            elif left == 'm':
                value = 5.1 if token.startswith('m') else 4.35
            else:
                value = 4.25 if len(left) == 1 else (
                    2.0 if len(left) == 2 else 0.8)
        elif len(left) <= 1:
            if right[0] in 'thk':
                value = 0.03
            elif right == 's':
                value = 2.1 if raw[:1].isspace() else 3.5
            elif right[0] == 'c':
                value = 1.2 if len(right) == 1 else 0.2
            elif right[0] in 'arou':
                value = 1.4 if len(right) < 5 else 0.9
            else:
                value = 0.95 / (1.0 + 0.2 * (len(right) - 1))
        elif right.startswith('i') and len(left) <= 3:
            value = 0.6
    elif token.startswith('Mc'):
        value = 0.9
    elif word.endswith(('uc', 'yc')) and len(word) <= 4:
        value = 0.65
    elif word in ('bc', 'dc'):
        value = 0.8
    elif word == 'ак':
        value = 0.9
    elif word == 'аци':
        value = 1.9
    return None, float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 1790: an "ac" letter-chunk detector.

The component reads only the current token. It fires when that token's letters
(case ignored, punctuation and spaces dropped) contain "ac" as a short standalone
piece:
  * the piece "ac" itself, as in "AC", " ac", "ac" (strongest, about 4.5);
  * one letter then "ac", as in "Mac", "Vac", "fac", "sac" (about 3.5);
  * "across" and short words starting "ac" (acad, acid, acne, acet) (about 2);
  * "-ace" words like "race", "face", "lace" (about 1).
Words where "ac" is just part of a common word, such as "each", "back", "place",
"space", "act", "accident", stay at 0.

Scores are in the component's own activation units, so no rescaling is needed.
"""

import re

READS = ()
LETTERS = re.compile(r"[^a-z]")


def piece_value(token: str) -> float:
    core = LETTERS.sub("", token.lower())
    if core == "ac":
        return 4.5
    if re.fullmatch(r"[a-z]ac", core):
        return 3.5
    if core == "across":
        return 2.0
    if re.fullmatch(r"ac[a-z]{0,3}", core) and core[:3] not in ("acc", "act", "ack", "ach"):
        return 2.0
    if re.fullmatch(r"[a-z]ace?", core) and core[0] not in "ps":
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    # The activation depends only on the token being read at this position.
    return None, float(piece_value(prefix.token_strings[-1]))

